};
var SISTEMA_AVALIACAO = 'Você é especialista em captação de recursos para instituições científicas e de inovação do Distrito Federal. Avalia editais com realismo: confere as exigências contra os documentos e projetos que a instituição tem, não superestima a aderência, aponta o que falta e escreve em português claro e direto, para quem vai decidir se vai atrás.';

// Valida a saída da IA e monta a linha da avaliação. Saída inválida ou token malformado: gravar=false (nada é gravado; volta na rodada seguinte).
function linhaAvaliacao(f, pedido, ia, token, agoraIso) {
  if (!ia || typeof ia !== 'object' || Array.isArray(ia)) return { gravar: false, motivo: 'saída da IA ausente ou inválida' };
