    if (!ref) return;
    var n = Number(a.pedidos_resultado) || 0;
    if (n >= 2) return;
    var devido = n === 0 ? (hoje >= somaDias(ref, 30) && (!env || hoje >= somaDias(env, 7))) : (hoje >= somaDias(ref, 60) && hoje >= somaDias(dia(a.pedido_resultado_em) || ref, 30));
    if (devido) tarefas.push(Object.assign({ tipo: 'pedido_resultado', pedidos_novos: n + 1 }, base));
  });
  return tarefas;
}
function leituraDe(op) {
  var u = seguro(op.link_edital_oficial) || seguro(op.url);
  if (!u) return 'sem_pagina';
  return txt(op.texto_fonte) && (ehApiTransferegov(u) || ehApiTransferegov(op.url) || /^https?:\/\/(ec\.europa\.eu|api\.tech\.ec\.europa\.eu)\//i.test(u)) ? 'sem_pagina' : 'buscar';
}

// ---------- leitura do edital ----------
function validade(v) {
  var s = txt(v), m = s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return m[3] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2);
  m = s.match(/(\d{4})-(\d{2})-(\d{2})/); return m ? m[0] : '';
}
// Texto do edital (PDF, página ou só o texto da coleta) e pedido à IA. dossie: linhas da aba; op: linha da oportunidade.
function montarPedidoLeitura(f, resp, dossie, op, hoje) {
  resp = resp || {};
  var base = txt(op.texto_fonte), pag = '', fonte = '';
  if (f.leitura !== 'sem_pagina' && !resp.error) {
    if (typeof resp.text === 'string') { pag = resp.text; fonte = 'PDF'; }
    else if (typeof resp.data === 'string') { pag = lerHtml(resp.data); fonte = 'página'; }
  }
  var texto = pag && base && tam(pag) < 400 ? base + '\n\n--- PÁGINA ---\n' + pag : (pag || base);
  if (!pag || tam(pag) < 400) fonte = base ? 'texto da coleta' : (fonte || 'página');
  texto = texto.slice(0, LIMITE_TEXTO);
  var leituraOk = tam(texto) >= 400;
  var pend = [], linhas = [];
  (dossie || []).forEach(function (d) {
    if (!d || !txt(d['Item']) || ehCertidao(d)) return;
    var sit = txt(d['Situação']), val = validade(d['Validade']), estado = '';
    if (/^(falta|verificar)/i.test(sit)) estado = sit.charAt(0).toUpperCase() + sit.slice(1).toLowerCase();
    else if (val && val < hoje) estado = 'Vencido em ' + val;
    else if (val && f.prazo && val <= f.prazo) estado = 'Vence em ' + val + ', antes do prazo do edital';
    linhas.push('- ' + txt(d['Item']) + ': ' + (estado || sit || 'sem situação'));
    if (estado) pend.push({ item: txt(d['Item']), estado: estado });
  });
  var i = infoOp(op);
  var prompt = 'Hoje é ' + hoje + '. O Modal decidiu concorrer a esta oportunidade. Leia o texto e extraia o que ele precisa entregar.\n\n' +
    'EDITAL\n- Título: ' + i.titulo + '\n- Ofertante: ' + i.ofertante + '\n- Prazo registrado: ' + (f.prazo || 'não informado') + '\n- Link: ' + (i.link.tg ? '(programa do Transferegov)' : i.link.url) + '\n\n' +
    'ITENS DO DOSSIÊ DO MODAL (nome exato: situação)\n' + (linhas.join('\n') || '(dossiê vazio)') + '\n\n' +
    'Instruções:\n' +
    '- documentos_exigidos: documentos e anexos que a proposta ou a habilitação exige, um item curto por documento, na ordem do texto. Não inclua certidões negativas aqui. Não invente: só o que o texto pede.\n' +
    '- exige_certidoes: "sim" se o texto pede certidões negativas ou de regularidade (fiscal federal, FGTS, trabalhista, distrital/estadual/municipal), "nao" se o texto completo foi lido e não pede, "nao_informado" se o texto não permite saber.\n' +
    '- certidoes: quais o texto pede, só com estes códigos: federal, fgts, trabalhista, df. Lista vazia se não pede.\n' +
    '- outras_certidoes: outras certidões pedidas (ex.: certidão do conselho, de falência), texto curto.\n' +
    '- itens_dossie_exigidos: para cada item da lista do dossiê acima que o texto exige e que está como Falta, Não tem, Não se aplica (providenciar para este projeto), Verificar, vencido ou vencendo antes do prazo: "item" com o nome EXATO copiado da lista e "trecho" com a frase do edital, copiada literalmente, que o exige. Lista vazia se nenhum.\n' +
    '- forma_entrega: como e onde a proposta é entregue (sistema, e-mail, protocolo), em uma frase; vazio se o texto não diz.\n' +
    '- prazo_no_edital: a data limite de envio que aparece no texto, AAAA-MM-DD; vazio se não aparece.\n\n' +
    'TEXTO (' + (leituraOk ? fonte : 'não lido') + ')\n' + (leituraOk ? texto : '(não foi possível ler o edital; responda exige_certidoes "nao_informado" e listas vazias)');
  return { prompt: prompt, texto: texto, leitura_ok: leituraOk, fonte: fonte, dossie_pendente: pend };
}

// Confere a leitura da IA (lado cauteloso): "não exige certidões" só vale com PDF ou texto longo; item do dossiê só entra com trecho citado
// que existe de fato no texto lido e que não repete a avaliação; certidões negativas saem de documentos_exigidos.
var CERT_DOC = /certid[aã]o negativa|certid[aã]o de d[eé]bitos|cndt|regularidade (do|com o|perante o) fgts|\bcrf\b|d[eé]bitos trabalhistas|d[ií]vida ativa|regularidade fiscal/i;
function conferirLeitura(ia, pedido, aval) {
  if (!ia || typeof ia !== 'object') return null;
  var out = Object.assign({}, ia);
  var texto = normTxt(pedido.texto);
  var jaNaAvaliacao = itensDe(aval && aval.requisitos_faltantes).map(normTxt);
  if (out.exige_certidoes === 'nao' && !(pedido.fonte === 'PDF' || tam(pedido.texto) >= 12000)) out.exige_certidoes = 'nao_informado';
  var outras = (Array.isArray(out.outras_certidoes) ? out.outras_certidoes : []).filter(function (d) { return !CERT_DOC.test(String(d)); });
  out.documentos_exigidos = (Array.isArray(out.documentos_exigidos) ? out.documentos_exigidos : []).filter(function (d) { return !CERT_DOC.test(String(d)); }).concat(outras);
  out.outras_certidoes = [];
  var descartados = [];
  out.itens_dossie_exigidos = (Array.isArray(out.itens_dossie_exigidos) ? out.itens_dossie_exigidos : []).filter(function (x) {
    var item = typeof x === 'string' ? x : (x && x.item), tr = normTxt(x && x.trecho);
    var ok = !!item && tr.length >= 10 && texto.indexOf(tr) >= 0 && jaNaAvaliacao.indexOf(normTxt(item)) < 0;
    if (!ok && item) descartados.push(item);
    return ok;
  }).map(function (x) { return typeof x === 'string' ? x : x.item; });
