}

// Captação – Acompanhamento: pacote "Vamos concorrer", lembretes 14/7/3/1, "Vocês enviaram?" e pedidos de resultado.
// Funções puras; embutido depois de comum.js e avaliacao.js (ehCertidao, lerHtml, LIMITE_TEXTO).

var MARCOS = [14, 7, 3, 1];
var LIMITE_PACOTES = 3;
var PADRAO_DIAS = 25;
var ESQUEMA_LEITURA = {
  type: 'object',
  properties: {
    documentos_exigidos: { type: 'array', items: { type: 'string' } },
    exige_certidoes: { type: 'string', enum: ['sim', 'nao', 'nao_informado'] },
    certidoes: { type: 'array', items: { type: 'string', enum: ['federal', 'fgts', 'trabalhista', 'df'] } },
    outras_certidoes: { type: 'array', items: { type: 'string' } },
    itens_dossie_exigidos: { type: 'array', items: { type: 'object', properties: { item: { type: 'string', description: 'nome exato do item do dossiê' }, trecho: { type: 'string', description: 'frase do edital, copiada literalmente, que exige este item' } }, required: ['item', 'trecho'] } },
    forma_entrega: { type: 'string' },
    prazo_no_edital: { type: 'string', description: 'AAAA-MM-DD ou vazio' }
  },
  required: ['documentos_exigidos', 'exige_certidoes', 'certidoes', 'outras_certidoes', 'itens_dossie_exigidos', 'forma_entrega', 'prazo_no_edital']
};
var SISTEMA_LEITURA = 'Você ajuda uma instituição científica e de inovação do Distrito Federal a preparar propostas para editais. Lê o edital com atenção e extrai só o que está escrito nele, em português claro e curto. Não inventa exigências. Em itens_dossie_exigidos, para cada item informe em "trecho" a frase do edital, copiada literalmente (de 10 a 200 caracteres), que exige aquele documento ou registro; se nenhuma frase do edital o exige expressamente, não inclua o item. Em documentos_exigidos não liste certidões negativas nem certificados de regularidade (eles vão em certidoes).';

function enviadosDe(a) { return txt(a.lembretes_enviados).split(',').map(function (s) { return Number(s.trim()); }).filter(function (n) { return n > 0; }); }

// ---------- o que sai nesta rodada ----------
// o: { avaliacoes, oportunidades, ctx, hoje, hora, agoraIso }. Cada coisa sai uma vez por avaliação; as colunas de controle só são gravadas depois do envio confirmado.
function planejar(o) {
  var ops = {};
  (o.oportunidades || []).forEach(function (x) { if (x && x.chave) ops[x.chave] = x; });
  // lembretes e pedidos só em horário comercial (8h às 20h) em produção; o pacote sai em qualquer rodada
  var janela = !o.ctx.producao || (o.hora >= 8 && o.hora < 20);
  var hoje = o.hoje, tarefas = [], pacotes = 0;
  (o.avaliacoes || []).forEach(function (a) {
    if (!a || !a.id || !a.chave_oportunidade) return;
    if (a.situacao !== 'concorrer' && a.situacao !== 'enviada') return;
    var op = ops[a.chave_oportunidade]; if (!op) return;
    // produção ignora oportunidades de teste; fora da produção só as de teste são tocadas
    if (o.ctx.producao === ehTeste(op)) return;
    var prazo = dia(op.prazo), dias = prazo ? diasEntre(hoje, prazo) : null;
    var base = { avaliacao_id: a.id, chave: a.chave_oportunidade, prazo: prazo, dias: dias, hoje: hoje };
    if (a.situacao === 'concorrer') {
      if (!a.pacote_enviado_em && !(prazo && dias < 0)) {
        var ini = a.pacote_iniciado_em ? Date.parse(String(a.pacote_iniciado_em)) : NaN;
        if (!isNaN(ini) && (Date.parse(o.agoraIso) - ini) < 30 * 60000) return; // outra rodada está montando
        if (pacotes >= LIMITE_PACOTES) return;
        pacotes++;
        tarefas.push(Object.assign({ tipo: 'pacote', url: seguro(op.link_edital_oficial) || seguro(op.url), leitura: leituraDe(op) }, base));
        return;
      }
      if (!janela) return;
      if (prazo && dias >= 1) {
        if (!a.pacote_enviado_em) return;
        var feitos = enviadosDe(a);
        var devidos = MARCOS.filter(function (m) { return m >= dias; });
        if (!devidos.length) return;
        var marco = Math.min.apply(null, devidos); // marco perdido não gera envio atrasado do anterior: só o mais próximo
        if (feitos.indexOf(marco) >= 0) return;
        var novos = feitos.concat(devidos).filter(function (v, i, arr) { return arr.indexOf(v) === i; }).sort(function (x, y) { return y - x; });
        tarefas.push(Object.assign({ tipo: 'lembrete', marco: marco, lembretes_novos: novos.join(',') }, base));
        return;
      }
      if (a.pedido_envio_em) return;
      if (prazo && dias < 0) { tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base)); return; }
      var dec = dia(a.decidido_em); // sem prazo registrado: pergunta uma vez, 30 dias depois da decisão
      if (!prazo && dec && hoje >= somaDias(dec, 30)) tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base));
      return;
    }
    // enviada: pedido de resultado 30 dias após o prazo e mais um 30 dias depois; nunca mais de dois
    if (!janela) return;
    var env = dia(a.enviada_em), ref = prazo || env;
    if (!ref) return;
    var n = Number(a.pedidos_resultado) || 0;
    if (n >= 2) return;
    var devido = n === 0 ? (hoje >= somaDias(ref, 30) && (!env || hoje >= somaDias(env, 7))) : (hoje >= somaDias(ref, 60) && hoje >= somaDias(dia(a.pedido_resultado_em) || ref, 30));
    if (devido) tarefas.push(Object.assign({ tipo: 'pedido_resultado', pedidos_novos: n + 1 }, base));
  });
  return tarefas;
}
function leituraDe(op) {
  var u = seguro(op.link_edital_oficial) || seguro(op.url);
  if (!u) return 'sem_pagina';
  return txt(op.texto_fonte) && (ehApiTransferegov(u) || ehApiTransferegov(op.url) || /^https?:\/\/(ec\.europa\.eu|api\.tech\.ec\.europa\.eu)\//i.test(u)) ? 'sem_pagina' : 'buscar';
}

// ---------- leitura do edital ----------
function validade(v) {
  var s = txt(v), m = s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return m[3] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2);
  m = s.match(/(\d{4})-(\d{2})-(\d{2})/); return m ? m[0] : '';
}
// Texto do edital (PDF, página ou só o texto da coleta) e pedido à IA. dossie: linhas da aba; op: linha da oportunidade.
function montarPedidoLeitura(f, resp, dossie, op, hoje) {
  resp = resp || {};
  var base = txt(op.texto_fonte), pag = '', fonte = '';
  if (f.leitura !== 'sem_pagina' && !resp.error) {
    if (typeof resp.text === 'string') { pag = resp.text; fonte = 'PDF'; }
    else if (typeof resp.data === 'string') { pag = lerHtml(resp.data); fonte = 'página'; }
  }
  var texto = pag && base && tam(pag) < 400 ? base + '\n\n--- PÁGINA ---\n' + pag : (pag || base);
  if (!pag || tam(pag) < 400) fonte = base ? 'texto da coleta' : (fonte || 'página');
  texto = texto.slice(0, LIMITE_TEXTO);
  var leituraOk = tam(texto) >= 400;
  var pend = [], linhas = [];
  (dossie || []).forEach(function (d) {
    if (!d || !txt(d['Item']) || ehCertidao(d)) return;
    var sit = txt(d['Situação']), val = validade(d['Validade']), estado = '';
    if (/^(falta|verificar)/i.test(sit)) estado = sit.charAt(0).toUpperCase() + sit.slice(1).toLowerCase();
    else if (val && val < hoje) estado = 'Vencido em ' + val;
    else if (val && f.prazo && val <= f.prazo) estado = 'Vence em ' + val + ', antes do prazo do edital';
    linhas.push('- ' + txt(d['Item']) + ': ' + (estado || sit || 'sem situação'));
    if (estado) pend.push({ item: txt(d['Item']), estado: estado });
  });
  var i = infoOp(op);
  var prompt = 'Hoje é ' + hoje + '. O Modal decidiu concorrer a esta oportunidade. Leia o texto e extraia o que ele precisa entregar.\n\n' +
    'EDITAL\n- Título: ' + i.titulo + '\n- Ofertante: ' + i.ofertante + '\n- Prazo registrado: ' + (f.prazo || 'não informado') + '\n- Link: ' + (i.link.tg ? '(programa do Transferegov)' : i.link.url) + '\n\n' +
    'ITENS DO DOSSIÊ DO MODAL (nome exato: situação)\n' + (linhas.join('\n') || '(dossiê vazio)') + '\n\n' +
    'Instruções:\n' +
    '- documentos_exigidos: documentos e anexos que a proposta ou a habilitação exige, um item curto por documento, na ordem do texto. Não inclua certidões negativas aqui. Não invente: só o que o texto pede.\n' +
    '- exige_certidoes: "sim" se o texto pede certidões negativas ou de regularidade (fiscal federal, FGTS, trabalhista, distrital/estadual/municipal), "nao" se o texto completo foi lido e não pede, "nao_informado" se o texto não permite saber.\n' +
    '- certidoes: quais o texto pede, só com estes códigos: federal, fgts, trabalhista, df. Lista vazia se não pede.\n' +
    '- outras_certidoes: outras certidões pedidas (ex.: certidão do conselho, de falência), texto curto.\n' +
    '- itens_dossie_exigidos: para cada item da lista do dossiê acima que o texto exige e que está como Falta, Não tem, Não se aplica (providenciar para este projeto), Verificar, vencido ou vencendo antes do prazo: "item" com o nome EXATO copiado da lista e "trecho" com a frase do edital, copiada literalmente, que o exige. Lista vazia se nenhum.\n' +
    '- forma_entrega: como e onde a proposta é entregue (sistema, e-mail, protocolo), em uma frase; vazio se o texto não diz.\n' +
    '- prazo_no_edital: a data limite de envio que aparece no texto, AAAA-MM-DD; vazio se não aparece.\n\n' +
    'TEXTO (' + (leituraOk ? fonte : 'não lido') + ')\n' + (leituraOk ? texto : '(não foi possível ler o edital; responda exige_certidoes "nao_informado" e listas vazias)');
  return { prompt: prompt, texto: texto, leitura_ok: leituraOk, fonte: fonte, dossie_pendente: pend };
}

// Confere a leitura da IA (lado cauteloso): "não exige certidões" só vale com PDF ou texto longo; item do dossiê só entra com trecho citado
// que existe de fato no texto lido e que não repete a avaliação; certidões negativas saem de documentos_exigidos.
var CERT_DOC = /certid[aã]o negativa|certid[aã]o de d[eé]bitos|cndt|regularidade (do|com o|perante o) fgts|\bcrf\b|d[eé]bitos trabalhistas|d[ií]vida ativa|regularidade fiscal/i;
function conferirLeitura(ia, pedido, aval) {
  if (!ia || typeof ia !== 'object') return null;
  var out = Object.assign({}, ia);
  var texto = normTxt(pedido.texto);
  var jaNaAvaliacao = itensDe(aval && aval.requisitos_faltantes).map(normTxt);
  if (out.exige_certidoes === 'nao' && !(pedido.fonte === 'PDF' || tam(pedido.texto) >= 12000)) out.exige_certidoes = 'nao_informado';
  var outras = (Array.isArray(out.outras_certidoes) ? out.outras_certidoes : []).filter(function (d) { return !CERT_DOC.test(String(d)); });
  out.documentos_exigidos = (Array.isArray(out.documentos_exigidos) ? out.documentos_exigidos : []).filter(function (d) { return !CERT_DOC.test(String(d)); }).concat(outras);
  out.outras_certidoes = [];
  var descartados = [];
  out.itens_dossie_exigidos = (Array.isArray(out.itens_dossie_exigidos) ? out.itens_dossie_exigidos : []).filter(function (x) {
    var item = typeof x === 'string' ? x : (x && x.item), tr = normTxt(x && x.trecho);
    var ok = !!item && tr.length >= 10 && texto.indexOf(tr) >= 0 && jaNaAvaliacao.indexOf(normTxt(item)) < 0;
    if (!ok && item) descartados.push(item);
    return ok;
  }).map(function (x) { return typeof x === 'string' ? x : x.item; });
  return { output: out, itens_descartados: descartados };
}

// ---------- cronograma de trás para a frente ----------
// Com 25 dias ou mais, o padrão; abaixo disso, os marcos são comprimidos na mesma proporção sem inverter a ordem (datas iguais viram um marco com várias ações).
function cronograma(prazo, hoje, certs, exige, prog) {
  var n = diasEntre(hoje, prazo);
  var passos = [
    { off: 21, acao: 'Reunir os documentos que faltam e pedir já os que dependem de outros órgãos ou de assinaturas' },
    { off: 18, acao: 'Definir o projeto, as metas e o orçamento da proposta' },
    { off: 10, acao: 'Ter o rascunho completo da proposta e do plano de trabalho' },
    { off: 7, acao: 'Revisão interna: conferir a proposta item por item contra ' + (prog ? 'as regras do programa' : 'o edital') },
    { off: 5, acao: certs.length ? 'Emitir as certidões ' + (exige === 'incerto' ? '(se o edital exigir) ' : '') + '— links abaixo' : '' },
    { off: 3, acao: 'Montar o pacote final: proposta, anexos e documentos assinados, nos formatos pedidos' },
    { off: 2, acao: 'Enviar a proposta, com margem antes do último dia, e guardar o comprovante' }
  ].filter(function (x) { return x.acao; });
  var marcos = [{ data: hoje, acao: prog ? 'Ler a descrição do programa inteira e anotar exigências, formato e canal de entrega' : 'Ler o edital inteiro e anotar exigências, formato e canal de entrega' }];
  var offs = passos.map(function (x) { return x.off === 2 ? (n >= 4 ? 2 : (n >= 2 ? 1 : 0)) : (n >= PADRAO_DIAS ? x.off : Math.round(x.off * n / PADRAO_DIAS)); });
  for (var i = offs.length - 2; i >= 0; i--) offs[i] = Math.max(offs[i], offs[i + 1]);
  passos.forEach(function (x, k) { marcos.push({ data: somaDias(prazo, -Math.max(0, Math.min(offs[k], n))), acao: x.acao }); });
  marcos.push({ data: prazo, acao: prog ? 'Data limite do programa para envio de propostas' : 'Prazo final do edital' });
  marcos.sort(function (a, b) { return a.data.localeCompare(b.data); });
  var out = [];
  marcos.forEach(function (m) { var u = out[out.length - 1]; if (u && u.data === m.data) u.acoes.push(m.acao); else out.push({ data: m.data, acoes: [m.acao] }); });
  var aviso;
  if (n >= PADRAO_DIAS) aviso = 'Faltam ' + n + ' dias: o prazo comporta o cronograma recomendado.';
  else if (n >= 10) aviso = 'Faltam ' + n + ' dias: o prazo é apertado e o cronograma foi compactado. Comecem pelos documentos que dependem de terceiros.';
  else if (n >= 4) aviso = 'Faltam só ' + n + ' dias: o prazo é curto e o cronograma foi compactado ao máximo. Só é realista se a proposta e a maior parte dos documentos já estiverem prontos.';
  else aviso = (n <= 0 ? 'O prazo termina hoje' : 'Faltam só ' + n + (n === 1 ? ' dia' : ' dias')) + ': o prazo já não comporta um cronograma de preparação. Só vale seguir se tudo já estiver pronto; se não estiver, o melhor é registrar a desistência pelo botão abaixo.';
  return { marcos: out, aviso: aviso };
}

function botoesPacote(token) { return BOTOES([{ rotulo: 'Enviamos a proposta', url: urlDecisao(token, 'enviada') }, { rotulo: 'Desistimos', url: urlDecisao(token, 'desistiu') }]); }
var NOTA_CONFIRMA = 'Cada botão abre uma página para confirmar; abrir o link sozinho não registra nada.';
var INTRO_PROGRAMA = 'Programa aberto a propostas, sem seleção. Não é um edital com concorrência: é um programa federal do Transferegov que recebe propostas voluntárias de organizações da sociedade civil até a data limite do programa. O Modal cadastra a proposta e o plano de trabalho no Transferegov (acesso com a conta gov.br de quem representa a instituição); o órgão concedente analisa o enquadramento e o orçamento disponível e pode ou não apoiar. Não há garantia de recurso: além de cadastrar a proposta, busquem apoio para o repasse junto à área técnica do órgão concedente. O cronograma abaixo usa a data limite do programa como prazo.';

// ---------- e-mail do pacote ----------
// ia: saída já conferida (ou null se a IA falhou ou o texto não foi lido). Devolve o e-mail com _marca para gravar depois do envio confirmado.
function montarPacote(o) {
  var f = o.tarefa, a = o.aval, op = o.op, i = infoOp(op), ia = o.ia, leu = !!(ia && o.leitura_ok);
  var prazo = f.prazo, hoje = f.hoje, n = prazo ? f.dias : null, prog = i.prog;
  var exige = 'incerto', certs = [];
  if (leu && ia.exige_certidoes === 'sim') { exige = 'sim'; certs = (Array.isArray(ia.certidoes) ? ia.certidoes : []).filter(function (c) { return ORDEM_CERT.indexOf(c) >= 0; }); if (!certs.length) certs = ORDEM_CERT.slice(); }
  else if (leu && ia.exige_certidoes === 'nao') exige = 'nao';
  else certs = ORDEM_CERT.slice();
  certs = ORDEM_CERT.filter(function (c) { return certs.indexOf(c) >= 0; });
  var docs = [];
  function add(s) { var k = normTxt(s); if (k && !docs.some(function (d) { return normTxt(d) === k; })) docs.push(s); }
  itensDe(a.requisitos_faltantes).forEach(add);
  var pend = o.dossie_pendente || [], ressalva = false;
  if (leu) { var pedidos = itensDe(ia.itens_dossie_exigidos).map(normTxt); pend.forEach(function (x) { if (pedidos.indexOf(normTxt(x.item)) >= 0) add(x.item + ' (dossiê: ' + x.estado.toLowerCase() + ')'); }); }
  else if (pend.length) { ressalva = true; pend.forEach(function (x) { add(x.item + ' (dossiê: ' + x.estado.toLowerCase() + '; confira se o edital exige)'); }); }
  if (leu) itensDe(ia.outras_certidoes).forEach(add);
  var exigidos = leu ? itensDe(ia.documentos_exigidos) : [];
  var crono = [], avisoPrazo;
  if (prazo) { var c = cronograma(prazo, hoje, certs, exige, prog); crono = c.marcos; avisoPrazo = c.aviso; }
  else avisoPrazo = 'O prazo não foi identificado: confiram a data no texto oficial. Sem prazo registrado, não há cronograma nem lembretes automáticos.';
  var b = [PT('O Modal confirmou que vai ' + (prog ? 'propor' : 'concorrer') + '. Este é o pacote para preparar a proposta até o prazo.')];
  if (prog) b.push(AV(INTRO_PROGRAMA, 'atencao'));
  b.push(H(prog ? 'Programa no Transferegov' : 'Edital oficial'));
  b.push(blocoLink(i));
  if (leu && txt(ia.forma_entrega)) b.push(P('<b>Como entregar:</b> ' + esc(ia.forma_entrega)));
  if (leu && /^\d{4}-\d{2}-\d{2}$/.test(txt(ia.prazo_no_edital)) && prazo && txt(ia.prazo_no_edital) !== prazo) b.push(AV('O texto indica ' + br(ia.prazo_no_edital) + ' como data limite, diferente da registrada (' + br(prazo) + '). Confiram no texto oficial e sigam a data dele.'));
  b.push(H('Prazo')); b.push(PT(avisoPrazo));
  b.push(H('Documentos que faltam'));
  b.push(docs.length ? UL(docs) : PT('Pela avaliação e pelo dossiê, nenhum documento consta como faltando. Confiram a lista do ' + (prog ? 'programa' : 'edital') + ' abaixo.'));
  if (ressalva) b.push(PT('O texto não pôde ser lido por inteiro: os itens do dossiê acima estão em falta ou vencidos, mas confiram se este ' + (prog ? 'programa' : 'edital') + ' os exige.'));
  if (!leu) b.push(AV('Não foi possível ler o texto completo automaticamente. Leiam a seção de documentos e habilitação no texto oficial.'));
  if (exigidos.length) { b.push(H('Documentos que o ' + (prog ? 'programa' : 'edital') + ' pede')); b.push(UL(exigidos.slice(0, 30))); }
  if (crono.length) { b.push(H('Cronograma até o prazo')); b.push(UL(crono.map(function (m) { return br(m.data) + ' — ' + m.acoes.join('; '); }))); }
  if (certs.length) {
    b.push(H('Certidões' + (exige === 'incerto' ? ' (se o edital exigir)' : '')));
    b.push(PT(exige === 'incerto' ? 'Não foi possível confirmar pelo texto se há exigência de certidões negativas. Se houver, emitam estas:' : 'O texto exige estas certidões. Emitam perto da entrega' + (prazo ? ' (no cronograma acima)' : '') + ', para que estejam válidas na data do envio:'));
    b.push(UL(certs.map(function (k) { return { texto: CERTS[k].nome + ' — ' + CERTS[k].nota, url: CERTS[k].url }; })));
    b.push(PT('Os sites têm verificação contra robôs, então a emissão é feita por uma pessoa. Salvem os PDFs e atualizem o dossiê.'));
  }
  var futuros = MARCOS.filter(function (m) { return prazo && m < n; });
  var lemb = futuros.length ? 'Esta lista recebe lembretes ' + futuros.map(function (m) { return m + (m === 1 ? ' dia' : ' dias'); }).join(', ') + ' antes do prazo. ' : (prazo ? 'O prazo já está perto demais para lembretes. ' : '');
  b.push(H('Lembretes')); b.push(PT(lemb + 'Quando enviarem a proposta, avisem pelo botão "Enviamos a proposta"; se desistirem, pelo botão "Desistimos". Assim os lembretes param. ' + NOTA_CONFIRMA));
  b.push(botoesPacote(a.token));
  return novoEmail(o.cfg, o.ctx, {
    assunto: (prog ? 'Vamos propor: pacote de preparação — ' : 'Vamos concorrer: pacote de preparação — ') + i.titulo + (prazo ? ' (até ' + br(prazo) + ')' : ''),
    etiqueta: prog ? 'Pacote: programa aberto' : 'Pacote: vamos concorrer', titulo: i.titulo, previa: 'Pacote de preparação' + (prazo ? ' · ' + (prog ? 'data limite ' : 'prazo ') + br(prazo) : ''), blocos: b,
    marca: {
      tipo: 'pacote', id: f.avaliacao_id, cronograma: JSON.stringify(crono), exige_certidoes: exige, certidoes_exigidas: certs.join(','),
      documentos_pendentes: docs.join('\n').slice(0, 3000),
