    assunto: (prog ? 'Vamos propor: pacote de preparação — ' : 'Vamos concorrer: pacote de preparação — ') + i.titulo + (prazo ? ' (até ' + br(prazo) + ')' : ''),
    etiqueta: prog ? 'Pacote: programa aberto' : 'Pacote: vamos concorrer', titulo: i.titulo, previa: 'Pacote de preparação' + (prazo ? ' · ' + (prog ? 'data limite ' : 'prazo ') + br(prazo) : ''), blocos: b,
