  b.push(H(prog ? 'Programa no Transferegov' : 'Edital oficial'));
  b.push(blocoLink(i));
  if (leu && txt(ia.forma_entrega)) b.push(P('<b>Como entregar:</b> ' + esc(ia.forma_entrega)));
  if (leu && /^\d{4}-\d{2}-\d{2}$/.test(txt(ia.prazo_no_edital)) && prazo && txt(ia.prazo_no_edital) !== prazo) b.push(AV('O texto indica ' + br(ia.prazo_no_edital) + ' como data limite, diferente da registrada (' + br(prazo) + '). Confiram no texto oficial e sigam a data dele.'));
  b.push(H('Prazo')); b.push(PT(avisoPrazo));
  b.push(H('Documentos que faltam'));
  b.push(docs.length ? UL(docs) : PT('Pela avaliação e pelo dossiê, nenhum documento consta como faltando. Confiram a lista do ' + (prog ? 'programa' : 'edital') + ' abaixo.'));
  if (ressalva) b.push(PT('O texto não pôde ser lido por inteiro: os itens do dossiê acima estão em falta ou vencidos, mas confiram se este ' + (prog ? 'programa' : 'edital') + ' os exige.'));
  if (!leu) b.push(AV('Não foi possível ler o texto completo automaticamente. Leiam a seção de documentos e habilitação no texto oficial.'));
  if (exigidos.length) { b.push(H('Documentos que o ' + (prog ? 'programa' : 'edital') + ' pede')); b.push(UL(exigidos.slice(0, 30))); }
  if (crono.length) { b.push(H('Cronograma até o prazo')); b.push(UL(crono.map(function (m) { return br(m.data) + ' — ' + m.acoes.join('; '); }))); }
  if (certs.length) {
    b.push(H('Certidões' + (exige === 'incerto' ? ' (se o edital exigir)' : '')));
    b.push(PT(exige === 'incerto' ? 'Não foi possível confirmar pelo texto se há exigência de certidões negativas. Se houver, emitam estas:' : 'O texto exige estas certidões. Emitam perto da entrega' + (prazo ? ' (no cronograma acima)' : '') + ', para que estejam válidas na data do envio:'));
    b.push(UL(certs.map(function (k) { return { texto: CERTS[k].nome + ' — ' + CERTS[k].nota, url: CERTS[k].url }; })));
    b.push(PT('Os sites têm verificação contra robôs, então a emissão é feita por uma pessoa. Salvem os PDFs e atualizem o dossiê.'));
  }
  var futuros = MARCOS.filter(function (m) { return prazo && m < n; });
  var lemb = futuros.length ? 'Esta lista recebe lembretes ' + futuros.map(function (m) { return m + (m === 1 ? ' dia' : ' dias'); }).join(', ') + ' antes do prazo. ' : (prazo ? 'O prazo já está perto demais para lembretes. ' : '');
  b.push(H('Lembretes')); b.push(PT(lemb + 'Quando enviarem a proposta, avisem pelo botão "Enviamos a proposta"; se desistirem, pelo botão "Desistimos". Assim os lembretes param. ' + NOTA_CONFIRMA));
  b.push(botoesPacote(a.token));
  return novoEmail(o.cfg, o.ctx, {
    assunto: (prog ? 'Vamos propor: pacote de preparação — ' : 'Vamos concorrer: pacote de preparação — ') + i.titulo + (prazo ? ' (até ' + br(prazo) + ')' : ''),
    etiqueta: prog ? 'Pacote: programa aberto' : 'Pacote: vamos concorrer', titulo: i.titulo, previa: 'Pacote de preparação' + (prazo ? ' · ' + (prog ? 'data limite ' : 'prazo ') + br(prazo) : ''), blocos: b,
    marca: {
      tipo: 'pacote', id: f.avaliacao_id, cronograma: JSON.stringify(crono), exige_certidoes: exige, certidoes_exigidas: certs.join(','),
      documentos_pendentes: docs.join('\n').slice(0, 3000),
      // marcos já alcançados quando o pacote sai contam como cobertos
