}

// ---------- lembretes e pedidos ----------
function montarLembretes(o) {
  var avals = {}, ops = {};
  (o.avaliacoes || []).forEach(function (a) { if (a && a.id) avals[a.id] = a; });
  (o.oportunidades || []).forEach(function (x) { if (x && x.chave) ops[x.chave] = x; });
  var saida = [];
  (o.tarefas || []).forEach(function (t) {
    var a = avals[t.avaliacao_id], op = ops[t.chave];
    if (!a || !op) return;
    var i = infoOp(op), prog = i.prog, rotuloPrazo = prog ? 'Data limite do programa' : 'Prazo';
    var oque = prog ? 'este programa aberto a propostas' : 'este edital';
    var botoes = BOTOES([{ rotulo: 'Enviamos a proposta', url: urlDecisao(a.token, 'enviada') }, { rotulo: 'Desistimos', url: urlDecisao(a.token, 'desistiu') }]);
    var campos = CAMPOS([{ rotulo: rotuloPrazo, valor: i.prazo ? br(i.prazo) : 'não informado' }, { rotulo: 'Ofertante', valor: i.ofertante || 'não informado' }]);
    if (t.tipo === 'lembrete') {
      var n = t.dias, crono = [];
      try { crono = JSON.parse(a.cronograma || '[]'); } catch (e) { crono = []; }
      var proximos = (Array.isArray(crono) ? crono : []).filter(function (c) { return c && c.data >= t.hoje; });
      var docs = itensDe(a.documentos_pendentes);
      var certs = txt(a.certidoes_exigidas).split(',').map(function (s) { return s.trim(); }).filter(function (c) { return CERTS[c]; });
      var b = [PT('O Modal está ' + (prog ? 'propondo a ' : 'concorrendo a ') + oque + '. ' + (n === 1 ? 'O prazo termina amanhã.' : 'Faltam ' + n + ' dias para ' + (prog ? 'a data limite' : 'o prazo') + '.') + ' Se a proposta já foi enviada, avisem pelo botão "Enviamos a proposta" e os lembretes param.'), campos];
      if (proximos.length) { b.push(H('Próximos passos do cronograma')); b.push(UL(proximos.map(function (c) { return br(c.data) + ' — ' + (c.acoes || []).join('; '); }))); }
      if (docs.length) { b.push(H('Documentos que faltavam no pacote')); b.push(UL(docs)); b.push(PT('Se algum já foi resolvido, atualizem o dossiê.')); }
      if (certs.length && n <= 7) { b.push(H('Certidões' + (a.exige_certidoes === 'incerto' ? ' (se o edital exigir)' : ''))); b.push(PT('É a hora de emitir, para que estejam válidas no envio:')); b.push(UL(certs.map(function (k) { return { texto: CERTS[k].nome, url: CERTS[k].url }; }))); }
      b.push(blocoLink(i)); b.push(PT(NOTA_CONFIRMA)); b.push(botoes);
      saida.push(novoEmail(o.cfg, o.ctx, { assunto: 'Lembrete: ' + faltam(n) + ' — ' + i.titulo, etiqueta: 'Lembrete de prazo', titulo: i.titulo, previa: 'Lembrete · ' + rotuloPrazo.toLowerCase() + ' ' + br(i.prazo), blocos: b, marca: { tipo: 'lembrete', id: a.id, lembretes_enviados: t.lembretes_novos } }));
    } else if (t.tipo === 'pedido_envio') {
      var b2 = [PT('O Modal tinha decidido ' + (prog ? 'propor a ' : 'concorrer a ') + oque + (t.prazo ? ', cuja ' + (prog ? 'data limite' : 'prazo') + ' já terminou' : '') + '. Vocês enviaram a proposta?'), PT('Respondam pelo botão: "Enviamos a proposta" se enviaram, ou "Desistimos" se não enviaram. Esta é a única pergunta sobre o envio. ' + NOTA_CONFIRMA), campos, blocoLink(i), botoes];
      saida.push(novoEmail(o.cfg, o.ctx, { assunto: 'Vocês enviaram a proposta? — ' + i.titulo + (t.prazo ? ' (prazo em ' + br(t.prazo) + ')' : ''), etiqueta: 'Acompanhamento: envio', titulo: i.titulo, previa: 'Pedido de confirmação de envio', blocos: b2, marca: { tipo: 'pedido_envio', id: a.id } }));
    } else if (t.tipo === 'pedido_resultado') {
      var segundo = t.pedidos_novos >= 2;
      var b3 = [PT('O Modal enviou a proposta para ' + oque + '. Já saiu o resultado?'), PT('Se saiu, respondam pelo botão "Ganhamos" ou "Perdemos". Se o Modal abriu mão da proposta, usem "Desistimos". ' + (segundo ? 'Este é o último pedido automático; quando o resultado sair, os botões continuam valendo.' : 'Se o resultado ainda não saiu, não precisa responder: voltamos a perguntar uma única vez daqui a 30 dias.') + ' ' + NOTA_CONFIRMA), campos, blocoLink(i),
        BOTOES([{ rotulo: 'Ganhamos', url: urlDecisao(a.token, 'ganhou') }, { rotulo: 'Perdemos', url: urlDecisao(a.token, 'perdeu') }, { rotulo: 'Desistimos', url: urlDecisao(a.token, 'desistiu') }])];
      saida.push(novoEmail(o.cfg, o.ctx, { assunto: 'Já saiu o resultado? — ' + i.titulo, etiqueta: 'Acompanhamento: resultado', titulo: i.titulo, previa: 'Pedido de resultado', blocos: b3, marca: { tipo: 'pedido_resultado', id: a.id, pedidos_resultado: t.pedidos_novos } }));
