  var offs = passos.map(function (x) { return x.off === 2 ? (n >= 4 ? 2 : (n >= 2 ? 1 : 0)) : (n >= PADRAO_DIAS ? x.off : Math.round(x.off * n / PADRAO_DIAS)); });
  for (var i = offs.length - 2; i >= 0; i--) offs[i] = Math.max(offs[i], offs[i + 1]);
  passos.forEach(function (x, k) { marcos.push({ data: somaDias(prazo, -Math.max(0, Math.min(offs[k], n))), acao: x.acao }); });
  marcos.push({ data: prazo, acao: prog ? 'Data limite do programa para envio de propostas' : 'Prazo final do edital' });
  marcos.sort(function (a, b) { return a.data.localeCompare(b.data); });
  var out = [];
  marcos.forEach(function (m) { var u = out[out.length - 1]; if (u && u.data === m.data) u.acoes.push(m.acao); else out.push({ data: m.data, acoes: [m.acao] }); });
