  else if (n >= 10) aviso = 'Faltam ' + n + ' dias: o prazo é apertado e o cronograma foi compactado. Comecem pelos documentos que dependem de terceiros.';
  else if (n >= 4) aviso = 'Faltam só ' + n + ' dias: o prazo é curto e o cronograma foi compactado ao máximo. Só é realista se a proposta e a maior parte dos documentos já estiverem prontos.';
