};
var SISTEMA_LEITURA = 'Você ajuda uma instituição científica e de inovação do Distrito Federal a preparar propostas para editais. Lê o edital com atenção e extrai só o que está escrito nele, em português claro e curto. Não inventa exigências. Em itens_dossie_exigidos, para cada item informe em "trecho" a frase do edital, copiada literalmente (de 10 a 200 caracteres), que exige aquele documento ou registro; se nenhuma frase do edital o exige expressamente, não inclua o item. Em documentos_exigidos não liste certidões negativas nem certificados de regularidade (eles vão em certidoes).';

function enviadosDe(a) { return txt(a.lembretes_enviados).split(',').map(function (s) { return Number(s.trim()); }).filter(function (n) { return n > 0; }); }

// ---------- o que sai nesta rodada ----------
// o: { avaliacoes, oportunidades, ctx, hoje, hora, agoraIso }. Cada coisa sai uma vez por avaliação; as colunas de controle só são gravadas depois do envio confirmado.
function planejar(o) {
  var ops = {};
  (o.oportunidades || []).forEach(function (x) { if (x && x.chave) ops[x.chave] = x; });
  // lembretes e pedidos só em horário comercial (8h às 20h) em produção; o pacote sai em qualquer rodada
  var janela = !o.ctx.producao || (o.hora >= 8 && o.hora < 20);
  var hoje = o.hoje, tarefas = [], pacotes = 0;
  (o.avaliacoes || []).forEach(function (a) {
    if (!a || !a.id || !a.chave_oportunidade) return;
    if (a.situacao !== 'concorrer' && a.situacao !== 'enviada') return;
    var op = ops[a.chave_oportunidade]; if (!op) return;
    // produção ignora oportunidades de teste; fora da produção só as de teste são tocadas
    if (o.ctx.producao === ehTeste(op)) return;
    var prazo = dia(op.prazo), dias = prazo ? diasEntre(hoje, prazo) : null;
    var base = { avaliacao_id: a.id, chave: a.chave_oportunidade, prazo: prazo, dias: dias, hoje: hoje };
    if (a.situacao === 'concorrer') {
      if (!a.pacote_enviado_em && !(prazo && dias < 0)) {
        var ini = a.pacote_iniciado_em ? Date.parse(String(a.pacote_iniciado_em)) : NaN;
        if (!isNaN(ini) && (Date.parse(o.agoraIso) - ini) < 30 * 60000) return; // outra rodada está montando
        if (pacotes >= LIMITE_PACOTES) return;
        pacotes++;
        tarefas.push(Object.assign({ tipo: 'pacote', url: seguro(op.link_edital_oficial) || seguro(op.url), leitura: leituraDe(op) }, base));
        return;
      }
      if (!janela) return;
      if (prazo && dias >= 1) {
        if (!a.pacote_enviado_em) return;
        var feitos = enviadosDe(a);
        var devidos = MARCOS.filter(function (m) { return m >= dias; });
        if (!devidos.length) return;
        var marco = Math.min.apply(null, devidos); // marco perdido não gera envio atrasado do anterior: só o mais próximo
        if (feitos.indexOf(marco) >= 0) return;
        var novos = feitos.concat(devidos).filter(function (v, i, arr) { return arr.indexOf(v) === i; }).sort(function (x, y) { return y - x; });
        tarefas.push(Object.assign({ tipo: 'lembrete', marco: marco, lembretes_novos: novos.join(',') }, base));
        return;
      }
      if (a.pedido_envio_em) return;
      if (prazo && dias < 0) { tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base)); return; }
      var dec = dia(a.decidido_em); // sem prazo registrado: pergunta uma vez, 30 dias depois da decisão
      if (!prazo && dec && hoje >= somaDias(dec, 30)) tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base));
      return;
    }
    // enviada: pedido de resultado 30 dias após o prazo e mais um 30 dias depois; nunca mais de dois
    if (!janela) return;
    var env = dia(a.enviada_em), ref = prazo || env;
    if (!ref) return;
    var n = Number(a.pedidos_resultado) || 0;
    if (n >= 2) return;
    var devido = n === 0 ? (hoje >= somaDias(ref, 30) && (!env || hoje >= somaDias(env, 7))) : (hoje >= somaDias(ref, 60) && hoje >= somaDias(dia(a.pedido_resultado_em) || ref, 30));
    if (devido) tarefas.push(Object.assign({ tipo: 'pedido_resultado', pedidos_novos: n + 1 }, base));
  });
  return tarefas;
}
function leituraDe(op) {
  var u = seguro(op.link_edital_oficial) || seguro(op.url);
  if (!u) return 'sem_pagina';
  return txt(op.texto_fonte) && (ehApiTransferegov(u) || ehApiTransferegov(op.url) || /^https?:\/\/(ec\.europa\.eu|api\.tech\.ec\.europa\.eu)\//i.test(u)) ? 'sem_pagina' : 'buscar';
}

// ---------- leitura do edital ----------
function validade(v) {
  var s = txt(v), m = s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return m[3] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2);
  m = s.match(/(\d{4})-(\d{2})-(\d{2})/); return m ? m[0] : '';
}
// Texto do edital (PDF, página ou só o texto da coleta) e pedido à IA. dossie: linhas da aba; op: linha da oportunidade.
function montarPedidoLeitura(f, resp, dossie, op, hoje) {
  resp = resp || {};
  var base = txt(op.texto_fonte), pag = '', fonte = '';
  if (f.leitura !== 'sem_pagina' && !resp.error) {
    if (typeof resp.text === 'string') { pag = resp.text; fonte = 'PDF'; }
    else if (typeof resp.data === 'string') { pag = lerHtml(resp.data); fonte = 'página'; }
  }
  var texto = pag && base && tam(pag) < 400 ? base + '\n\n--- PÁGINA ---\n' + pag : (pag || base);
  if (!pag || tam(pag) < 400) fonte = base ? 'texto da coleta' : (fonte || 'página');
  texto = texto.slice(0, LIMITE_TEXTO);
  var leituraOk = tam(texto) >= 400;
  var pend = [], linhas = [];
  (dossie || []).forEach(function (d) {
    if (!d || !txt(d['Item']) || ehCertidao(d)) return;
    var sit = txt(d['Situação']), val = validade(d['Validade']), estado = '';
    if (/^(falta|verificar)/i.test(sit)) estado = sit.charAt(0).toUpperCase() + sit.slice(1).toLowerCase();
    else if (val && val < hoje) estado = 'Vencido em ' + val;
    else if (val && f.prazo && val <= f.prazo) estado = 'Vence em ' + val + ', antes do prazo do edital';
    linhas.push('- ' + txt(d['Item']) + ': ' + (estado || sit || 'sem situação'));
    if (estado) pend.push({ item: txt(d['Item']), estado: estado });
  });
  var i = infoOp(op);
  var prompt = 'Hoje é ' + hoje + '. O Modal decidiu concorrer a esta oportunidade. Leia o texto e extraia o que ele precisa entregar.\n\n' +
    'EDITAL\n- Título: ' + i.titulo + '\n- Ofertante: ' + i.ofertante + '\n- Prazo registrado: ' + (f.prazo || 'não informado') + '\n- Link: ' + (i.link.tg ? '(programa do Transferegov)' : i.link.url) + '\n\n' +
    'ITENS DO DOSSIÊ DO MODAL (nome exato: situação)\n' + (linhas.join('\n') || '(dossiê vazio)') + '\n\n' +
    'Instruções:\n' +
    '- documentos_exigidos: documentos e anexos que a proposta ou a habilitação exige, um item curto por documento, na ordem do texto. Não inclua certidões negativas aqui. Não invente: só o que o texto pede.\n' +
    '- exige_certidoes: "sim" se o texto pede certidões negativas ou de regularidade (fiscal federal, FGTS, trabalhista, distrital/estadual/municipal), "nao" se o texto completo foi lido e não pede, "nao_informado" se o texto não permite saber.\n' +
    '- certidoes: quais o texto pede, só com estes códigos: federal, fgts, trabalhista, df. Lista vazia se não pede.\n' +
    '- outras_certidoes: outras certidões pedidas (ex.: certidão do conselho, de falência), texto curto.\n' +
    '- itens_dossie_exigidos: para cada item da lista do dossiê acima que o texto exige e que está como Falta, Não tem, Não se aplica (providenciar para este projeto), Verificar, vencido ou vencendo antes do prazo: "item" com o nome EXATO copiado da lista e "trecho" com a frase do edital, copiada literalmente, que o exige. Lista vazia se nenhum.\n' +
    '- forma_entrega: como e onde a proposta é entregue (sistema, e-mail, protocolo), em uma frase; vazio se o texto não diz.\n' +
    '- prazo_no_edital: a data limite de envio que aparece no texto, AAAA-MM-DD; vazio se não aparece.\n\n' +
    'TEXTO (' + (leituraOk ? fonte : 'não lido') + ')\n' + (leituraOk ? texto : '(não foi possível ler o edital; responda exige_certidoes "nao_informado" e listas vazias)');
  return { prompt: prompt, texto: texto, leitura_ok: leituraOk, fonte: fonte, dossie_pendente: pend };
}

// Confere a leitura da IA (lado cauteloso): "não exige certidões" só vale com PDF ou texto longo; item do dossiê só entra com trecho citado
// que existe de fato no texto lido e que não repete a avaliação; certidões negativas saem de documentos_exigidos.
var CERT_DOC = /certid[aã]o negativa|certid[aã]o de d[eé]bitos|cndt|regularidade (do|com o|perante o) fgts|\bcrf\b|d[eé]bitos trabalhistas|d[ií]vida ativa|regularidade fiscal/i;
function conferirLeitura(ia, pedido, aval) {
  if (!ia || typeof ia !== 'object') return null;
  var out = Object.assign({}, ia);
  var texto = normTxt(pedido.texto);
  var jaNaAvaliacao = itensDe(aval && aval.requisitos_faltantes).map(normTxt);
  if (out.exige_certidoes === 'nao' && !(pedido.fonte === 'PDF' || tam(pedido.texto) >= 12000)) out.exige_certidoes = 'nao_informado';
  var outras = (Array.isArray(out.outras_certidoes) ? out.outras_certidoes : []).filter(function (d) { return !CERT_DOC.test(String(d)); });
  out.documentos_exigidos = (Array.isArray(out.documentos_exigidos) ? out.documentos_exigidos : []).filter(function (d) { return !CERT_DOC.test(String(d)); }).concat(outras);
  out.outras_certidoes = [];
  var descartados = [];
  out.itens_dossie_exigidos = (Array.isArray(out.itens_dossie_exigidos) ? out.itens_dossie_exigidos : []).filter(function (x) {
    var item = typeof x === 'string' ? x : (x && x.item), tr = normTxt(x && x.trecho);
    var ok = !!item && tr.length >= 10 && texto.indexOf(tr) >= 0 && jaNaAvaliacao.indexOf(normTxt(item)) < 0;
    if (!ok && item) descartados.push(item);
    return ok;
  }).map(function (x) { return typeof x === 'string' ? x : x.item; });
  return { output: out, itens_descartados: descartados };
}

// ---------- cronograma de trás para a frente ----------
// Com 25 dias ou mais, o padrão; abaixo disso, os marcos são comprimidos na mesma proporção sem inverter a ordem (datas iguais viram um marco com várias ações).
function cronograma(prazo, hoje, certs, exige, prog) {
  var n = diasEntre(hoje, prazo);
  var passos = [
    { off: 21, acao: 'Reunir os documentos que faltam e pedir já os que dependem de outros órgãos ou de assinaturas' },
    { off: 18, acao: 'Definir o projeto, as metas e o orçamento da proposta' },
    { off: 10, acao: 'Ter o rascunho completo da proposta e do plano de trabalho' },
    { off: 7, acao: 'Revisão interna: conferir a proposta item por item contra ' + (prog ? 'as regras do programa' : 'o edital') },
    { off: 5, acao: certs.length ? 'Emitir as certidões ' + (exige === 'incerto' ? '(se o edital exigir) ' : '') + '— links abaixo' : '' },
    { off: 3, acao: 'Montar o pacote final: proposta, anexos e documentos assinados, nos formatos pedidos' },
    { off: 2, acao: 'Enviar a proposta, com margem antes do último dia, e guardar o comprovante' }
  ].filter(function (x) { return x.acao; });
  var marcos = [{ data: hoje, acao: prog ? 'Ler a descrição do programa inteira e anotar exigências, formato e canal de entrega' : 'Ler o edital inteiro e anotar exigências, formato e canal de entrega' }];
  var offs = passos.map(function (x) { return x.off === 2 ? (n >= 4 ? 2 : (n >= 2 ? 1 : 0)) : (n >= PADRAO_DIAS ? x.off : Math.round(x.off * n / PADRAO_DIAS)); });
  for (var i = offs.length - 2; i >= 0; i--) offs[i] = Math.max(offs[i], offs[i + 1]);
  passos.forEach(function (x, k) { marcos.push({ data: somaDias(prazo, -Math.max(0, Math.min(offs[k], n))), acao: x.acao }); });
  marcos.push({ data: prazo, acao: prog ? 'Data limite do programa para envio de propostas' : 'Prazo final do edital' });
  marcos.sort(function (a, b) { return a.data.localeCompare(b.data); });
  var out = [];
  marcos.forEach(function (m) { var u = out[out.length - 1]; if (u && u.data === m.data) u.acoes.push(m.acao); else out.push({ data: m.data, acoes: [m.acao] }); });
  var aviso;
  if (n >= PADRAO_DIAS) aviso = 'Faltam ' + n + ' dias: o prazo comporta o cronograma recomendado.';
  else if (n >= 10) aviso = 'Faltam ' + n + ' dias: o prazo é apertado e o cronograma foi compactado. Comecem pelos documentos que dependem de terceiros.';
  else if (n >= 4) aviso = 'Faltam só ' + n + ' dias: o prazo é curto e o cronograma foi compactado ao máximo. Só é realista se a proposta e a maior parte dos documentos já estiverem prontos.';
  else aviso = (n <= 0 ? 'O prazo termina hoje' : 'Faltam só ' + n + (n === 1 ? ' dia' : ' dias')) + ': o prazo já não comporta um cronograma de preparação. Só vale seguir se tudo já estiver pronto; se não estiver, o melhor é registrar a desistência pelo botão abaixo.';
  return { marcos: out, aviso: aviso };
}

function botoesPacote(token) { return BOTOES([{ rotulo: 'Enviamos a proposta', url: urlDecisao(token, 'enviada') }, { rotulo: 'Desistimos', url: urlDecisao(token, 'desistiu') }]); }
var NOTA_CONFIRMA = 'Cada botão abre uma página para confirmar; abrir o link sozinho não registra nada.';
var INTRO_PROGRAMA = 'Programa aberto a propostas, sem seleção. Não é um edital com concorrência: é um programa federal do Transferegov que recebe propostas voluntárias de organizações da sociedade civil até a data limite do programa. O Modal cadastra a proposta e o plano de trabalho no Transferegov (acesso com a conta gov.br de quem representa a instituição); o órgão concedente analisa o enquadramento e o orçamento disponível e pode ou não apoiar. Não há garantia de recurso: além de cadastrar a proposta, busquem apoio para o repasse junto à área técnica do órgão concedente. O cronograma abaixo usa a data limite do programa como prazo.';

// ---------- e-mail do pacote ----------
// ia: saída já conferida (ou null se a IA falhou ou o texto não foi lido). Devolve o e-mail com _marca para gravar depois do envio confirmado.
function montarPacote(o) {
  var f = o.tarefa, a = o.aval, op = o.op, i = infoOp(op), ia = o.ia, leu = !!(ia && o.leitura_ok);
  var prazo = f.prazo, hoje = f.hoje, n = prazo ? f.dias : null, prog = i.prog;
  var exige = 'incerto', certs = [];
  if (leu && ia.exige_certidoes === 'sim') { exige = 'sim'; certs = (Array.isArray(ia.certidoes) ? ia.certidoes : []).filter(function (c) { return ORDEM_CERT.indexOf(c) >= 0; }); if (!certs.length) certs = ORDEM_CERT.slice(); }
  else if (leu && ia.exige_certidoes === 'nao') exige = 'nao';
  else certs = ORDEM_CERT.slice();
  certs = ORDEM_CERT.filter(function (c) { return certs.indexOf(c) >= 0; });
  var docs = [];
  function add(s) { var k = normTxt(s); if (k && !docs.some(function (d) { return normTxt(d) === k; })) docs.push(s); }
  itensDe(a.requisitos_faltantes).forEach(add);
  var pend = o.dossie_pendente || [], ressalva = false;
  if (leu) { var pedidos = itensDe(ia.itens_dossie_exigidos).map(normTxt); pend.forEach(function (x) { if (pedidos.indexOf(normTxt(x.item)) >= 0) add(x.item + ' (dossiê: ' + x.estado.toLowerCase() + ')'); }); }
  else if (pend.length) { ressalva = true; pend.forEach(function (x) { add(x.item + ' (dossiê: ' + x.estado.toLowerCase() + '; confira se o edital exige)'); }); }
  if (leu) itensDe(ia.outras_certidoes).forEach(add);
  var exigidos = leu ? itensDe(ia.documentos_exigidos) : [];
  var crono = [], avisoPrazo;
  if (prazo) { var c = cronograma(prazo, hoje, certs, exige, prog); crono = c.marcos; avisoPrazo = c.aviso; }
  else avisoPrazo = 'O prazo não foi identificado: confiram a data no texto oficial. Sem prazo registrado, não há cronograma nem lembretes automáticos.';
  var b = [PT('O Modal confirmou que vai ' + (prog ? 'propor' : 'concorrer') + '. Este é o pacote para preparar a proposta até o prazo.')];
  if (prog) b.push(AV(INTRO_PROGRAMA, 'atencao'));
  b.push(H(prog ? 'Programa no Transferegov' : 'Edital oficial'));
  b.push(blocoLink(i));
  if (leu && txt(ia.forma_entrega)) b.push(P('<b>Como entregar:</b> ' + esc(ia.forma_entrega)));
  if (leu && /^\d{4}-\d{2}-\d{2}$/.test(txt(ia.prazo_no_edital)) && prazo && txt(ia.prazo_no_edital) !== prazo) b.push(AV('O texto indica ' + br(ia.prazo_no_edital) + ' como data limite, diferente da registrada (' + br(prazo) + '). Confiram no texto oficial e sigam a data dele.'));
  b.push(H('Prazo')); b.push(PT(avisoPrazo));
  b.push(H('Documentos que faltam'));
  b.push(docs.length ? UL(docs) : PT('Pela avaliação e pelo dossiê, nenhum documento consta como faltando. Confiram a lista do ' + (prog ? 'programa' : 'edital') + ' abaixo.'));
  if (ressalva) b.push(PT('O texto não pôde ser lido por inteiro: os itens do dossiê acima estão em falta ou vencidos, mas confiram se este ' + (prog ? 'programa' : 'edital') + ' os exige.'));
  if (!leu) b.push(AV('Não foi possível ler o texto completo automaticamente. Leiam a seção de documentos e habilitação no texto oficial.'));
  if (exigidos.length) { b.push(H('Documentos que o ' + (prog ? 'programa' : 'edital') + ' pede')); b.push(UL(exigidos.slice(0, 30))); }
  if (crono.length) { b.push(H('Cronograma até o prazo')); b.push(UL(crono.map(function (m) { return br(m.data) + ' — ' + m.acoes.join('; '); }))); }
  if (certs.length) {
    b.push(H('Certidões' + (exige === 'incerto' ? ' (se o edital exigir)' : '')));
    b.push(PT(exige === 'incerto' ? 'Não foi possível confirmar pelo texto se há exigência de certidões negativas. Se houver, emitam estas:' : 'O texto exige estas certidões. Emitam perto da entrega' + (prazo ? ' (no cronograma acima)' : '') + ', para que estejam válidas na data do envio:'));
    b.push(UL(certs.map(function (k) { return { texto: CERTS[k].nome + ' — ' + CERTS[k].nota, url: CERTS[k].url }; })));
    b.push(PT('Os sites têm verificação contra robôs, então a emissão é feita por uma pessoa. Salvem os PDFs e atualizem o dossiê.'));
  }
  var futuros = MARCOS.filter(function (m) { return prazo && m < n; });
  var lemb = futuros.length ? 'Esta lista recebe lembretes ' + futuros.map(function (m) { return m + (m === 1 ? ' dia' : ' dias'); }).join(', ') + ' antes do prazo. ' : (prazo ? 'O prazo já está perto demais para lembretes. ' : '');
  b.push(H('Lembretes')); b.push(PT(lemb + 'Quando enviarem a proposta, avisem pelo botão "Enviamos a proposta"; se desistirem, pelo botão "Desistimos". Assim os lembretes param. ' + NOTA_CONFIRMA));
  b.push(botoesPacote(a.token));
  return novoEmail(o.cfg, o.ctx, {
    assunto: (prog ? 'Vamos propor: pacote de preparação — ' : 'Vamos concorrer: pacote de preparação — ') + i.titulo + (prazo ? ' (até ' + br(prazo) + ')' : ''),
    etiqueta: prog ? 'Pacote: programa aberto' : 'Pacote: vamos concorrer', titulo: i.titulo, previa: 'Pacote de preparação' + (prazo ? ' · ' + (prog ? 'data limite ' : 'prazo ') + br(prazo) : ''), blocos: b,
    marca: {
      tipo: 'pacote', id: f.avaliacao_id, cronograma: JSON.stringify(crono), exige_certidoes: exige, certidoes_exigidas: certs.join(','),
      documentos_pendentes: docs.join('\n').slice(0, 3000),
      // marcos já alcançados quando o pacote sai contam como cobertos
      lembretes_enviados: prazo && n >= 1 ? MARCOS.filter(function (m) { return m >= n; }).join(',') : ''
    }
  });
}

// ---------- lembretes e pedidos ----------
function montarLembretes(o) {
  var avals = {}, ops = {};
  (o.avaliacoes || []).forEach(function (a) { if (a && a.id) avals[a.id] = a; });
  (o.oportunidades || []).forEach(function (x) { if (x && x.chave) ops[x.chave] = x; });
  var saida = [];
  (o.tarefas || []).forEach(function (t) {
    var a = avals[t.avaliacao_id], op = ops[t.chave];
    if (!a || !op) return;
    var i = infoOp(op), prog = i.prog, rotuloPrazo = prog ? 'Data limite do programa' : 'Prazo';
    var oque = prog ? 'este programa aberto a propostas' : 'este edital';
    var botoes = BOTOES([{ rotulo: 'Enviamos a proposta', url: urlDecisao(a.token, 'enviada') }, { rotulo: 'Desistimos', url: urlDecisao(a.token, 'desistiu') }]);
    var campos = CAMPOS([{ rotulo: rotuloPrazo, valor: i.prazo ? br(i.prazo) : 'não informado' }, { rotulo: 'Ofertante', valor: i.ofertante || 'não informado' }]);
    if (t.tipo === 'lembrete') {
      var n = t.dias, crono = [];
      try { crono = JSON.parse(a.cronograma || '[]'); } catch (e) { crono = []; }
      var proximos = (Array.isArray(crono) ? crono : []).filter(function (c) { return c && c.data >= t.hoje; });
      var docs = itensDe(a.documentos_pendentes);
      var certs = txt(a.certidoes_exigidas).split(',').map(function (s) { return s.trim(); }).filter(function (c) { return CERTS[c]; });
      var b = [PT('O Modal está ' + (prog ? 'propondo a ' : 'concorrendo a ') + oque + '. ' + (n === 1 ? 'O prazo termina amanhã.' : 'Faltam ' + n + ' dias para ' + (prog ? 'a data limite' : 'o prazo') + '.') + ' Se a proposta já foi enviada, avisem pelo botão "Enviamos a proposta" e os lembretes param.'), campos];
      if (proximos.length) { b.push(H('Próximos passos do cronograma')); b.push(UL(proximos.map(function (c) { return br(c.data) + ' — ' + (c.acoes || []).join('; '); }))); }
      if (docs.length) { b.push(H('Documentos que faltavam no pacote')); b.push(UL(docs)); b.push(PT('Se algum já foi resolvido, atualizem o dossiê.')); }
      if (certs.length && n <= 7) { b.push(H('Certidões' + (a.exige_certidoes === 'incerto' ? ' (se o edital exigir)' : ''))); b.push(PT('É a hora de emitir, para que estejam válidas no envio:')); b.push(UL(certs.map(function (k) { return { texto: CERTS[k].nome, url: CERTS[k].url }; }))); }
      b.push(blocoLink(i)); b.push(PT(NOTA_CONFIRMA)); b.push(botoes);
      saida.push(novoEmail(o.cfg, o.ctx, { assunto: 'Lembrete: ' + faltam(n) + ' — ' + i.titulo, etiqueta: 'Lembrete de prazo', titulo: i.titulo, previa: 'Lembrete · ' + rotuloPrazo.toLowerCase() + ' ' + br(i.prazo), blocos: b, marca: { tipo: 'lembrete', id: a.id, lembretes_enviados: t.lembretes_novos } }));
    } else if (t.tipo === 'pedido_envio') {
      var b2 = [PT('O Modal tinha decidido ' + (prog ? 'propor a ' : 'concorrer a ') + oque + (t.prazo ? ', cuja ' + (prog ? 'data limite' : 'prazo') + ' já terminou' : '') + '. Vocês enviaram a proposta?'), PT('Respondam pelo botão: "Enviamos a proposta" se enviaram, ou "Desistimos" se não enviaram. Esta é a única pergunta sobre o envio. ' + NOTA_CONFIRMA), campos, blocoLink(i), botoes];
      saida.push(novoEmail(o.cfg, o.ctx, { assunto: 'Vocês enviaram a proposta? — ' + i.titulo + (t.prazo ? ' (prazo em ' + br(t.prazo) + ')' : ''), etiqueta: 'Acompanhamento: envio', titulo: i.titulo, previa: 'Pedido de confirmação de envio', blocos: b2, marca: { tipo: 'pedido_envio', id: a.id } }));
    } else if (t.tipo === 'pedido_resultado') {
      var segundo = t.pedidos_novos >= 2;
      var b3 = [PT('O Modal enviou a proposta para ' + oque + '. Já saiu o resultado?'), PT('Se saiu, respondam pelo botão "Ganhamos" ou "Perdemos". Se o Modal abriu mão da proposta, usem "Desistimos". ' + (segundo ? 'Este é o último pedido automático; quando o resultado sair, os botões continuam valendo.' : 'Se o resultado ainda não saiu, não precisa responder: voltamos a perguntar uma única vez daqui a 30 dias.') + ' ' + NOTA_CONFIRMA), campos, blocoLink(i),
        BOTOES([{ rotulo: 'Ganhamos', url: urlDecisao(a.token, 'ganhou') }, { rotulo: 'Perdemos', url: urlDecisao(a.token, 'perdeu') }, { rotulo: 'Desistimos', url: urlDecisao(a.token, 'desistiu') }])];
      saida.push(novoEmail(o.cfg, o.ctx, { assunto: 'Já saiu o resultado? — ' + i.titulo, etiqueta: 'Acompanhamento: resultado', titulo: i.titulo, previa: 'Pedido de resultado', blocos: b3, marca: { tipo: 'pedido_resultado', id: a.id, pedidos_resultado: t.pedidos_novos } }));
    }
  });
  return saida;
}

// Só marca o pacote que o subfluxo confirmou (resposta com id).
const email = $('E-mail do pacote').first().json || {};
return [{ json: Object.assign({ ok: enviado($input.first().json || {}) }, email._marca || {}) }];

// Captação – etapa 3: peças comuns (avaliação, avisos, decisão e acompanhamento).
// O gerador embute este arquivo antes do código de cada fluxo; os testes carregam os dois juntos (carregar.js).
// Sem dependências do n8n (nada de luxon): datas são texto AAAA-MM-DD no fuso de São Paulo.

var BASE_DECISAO = 'https://n8n.modal.org.br/webhook/captacao-decisao';
var BASE_REGISTRO = 'https://n8n.modal.org.br/webhook/captacao-decisao-registrar';
var TG_ENVIO = 'https://discricionarias.transferegov.sistema.gov.br/';
var TG_ROTULO = 'Enviar proposta no Transferegov (exige login gov.br)';
var RODAPE = 'Mensagem automática da captação de oportunidades do Instituto Modal.';
var ROTULO_PARCEIRA = 'Em parceria com uma empresa (cliente ou parceiro do Modal)';

var REC = { seguir: 'Seguir', avaliar: 'Avaliar', nao_seguir: 'Não seguir' };
var ESF = { baixo: 'Baixo', medio: 'Médio', alto: 'Alto' };
var SIT = { nova: 'Sem resposta', avisada: 'Sem resposta', concorrer: 'Vamos concorrer', talvez: 'Talvez', nao_serve: 'Não serve', enviada: 'Proposta enviada', ganhou: 'Ganhou', perdeu: 'Perdeu', desistiu: 'Desistiu' };
var DECIDIVEL = ['nova', 'avisada', 'talvez', 'concorrer'];
var CERTS = {
  federal: { nome: 'Certidão de débitos federais (Receita Federal e PGFN)', url: 'https://servicos.receitafederal.gov.br/servico/certidoes/', nota: 'informe o CNPJ; sai na hora quando não há pendência.' },
  fgts: { nome: 'Certificado de Regularidade do FGTS (CRF, Caixa)', url: 'https://consulta-crf.caixa.gov.br/consultacrf/pages/consultaEmpregador.jsf', nota: 'vale 30 dias e só pode ser renovado a partir de 5 dias antes de vencer: por isso é emitido perto da entrega.' },
  trabalhista: { nome: 'Certidão Negativa de Débitos Trabalhistas (CNDT, TST)', url: 'https://cndt-certidao.tst.jus.br/inicio.faces', nota: 'informe o CNPJ.' },
  df: { nome: 'Certidão negativa de débitos do Distrito Federal (Receita do DF, Secretaria de Economia)', url: 'https://ww1.receita.fazenda.df.gov.br/cidadao/certidoes/Certidao', nota: 'confira a validade impressa na certidão.' }
};
var ORDEM_CERT = ['federal', 'fgts', 'trabalhista', 'df'];

function txt(v) { return String(v == null ? '' : v).trim(); }
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }
// Só endereço público (mesma trava da triagem): o link do edital vem do texto lido pela IA e não pode levar o robô a serviço interno.
function enderecoPublico(u) {
  var m = String(u || '').trim().match(/^https?:\/\/([^\/?#:@]+)(:(?:80|443))?([\/?#]|$)/i);
  if (!m) return false;
  var h = m[1].toLowerCase().replace(/\.$/, '');
  // Nome de domínio comum: rótulos só com letras, números e hífen, terminando em domínio de letras
  // (recusa IP em qualquer grafia, como 0x7f.0.0.1 ou 0177.1, barra invertida e %).
  if (!/^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(h)) return false;
  if (/(^|\.)(localhost|local|internal|lan|home|arpa)$/.test(h)) return false;
  if (/(^|\.)modal\.org\.br$/.test(h)) return false;
  return true;
}
function seguro(u) { var v = txt(u); return /^https?:\/\/[^\s"'<>]+$/i.test(v) && enderecoPublico(v) ? v : ''; }
function normTxt(s) { return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function tam(s) { return String(s || '').replace(/\s+/g, '').length; }
function itensDe(v) { return (Array.isArray(v) ? v : String(v || '').split('\n')).map(function (s) { return String(s).replace(/^[-•*\s]+/, '').trim(); }).filter(Boolean); }

// ---------- datas (AAAA-MM-DD, fuso de São Paulo, sem horário de verão desde 2019) ----------
function dia(v) {
  if (v == null || v === '') return '';
  if (Object.prototype.toString.call(v) === '[object Date]') v = v.toISOString();
  var s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  var t = Date.parse(s);
  if (isNaN(t)) { var m = s.match(/^(\d{4}-\d{2}-\d{2})/); return m ? m[1] : ''; }
  return new Date(t - 3 * 3600 * 1000).toISOString().slice(0, 10);
}
function utc(iso) { return Date.parse(iso + 'T00:00:00Z'); }
function diasEntre(a, b) { return Math.round((utc(b) - utc(a)) / 86400000); }
function somaDias(iso, n) { return new Date(utc(iso) + n * 86400000).toISOString().slice(0, 10); }
function br(iso) { var m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : ''; }
function faltam(n) { return n <= 0 ? 'é hoje' : n === 1 ? 'falta 1 dia' : 'faltam ' + n + ' dias'; }
function porPrazo(a, b) { return (a.prazo || '9999-12-31').localeCompare(b.prazo || '9999-12-31'); }

// ---------- execução: produção x teste ----------
// Produção = fluxo gerado com --producao (modoTeste false) E execução agendada. Manual ou modoTeste: e-mail só para o endereço de teste,
// com [TESTE] no assunto, e só oportunidades "[TESTE]" têm a situação alterada. Em produção, "[TESTE]" é ignorado.
function contexto(cfg, modoN8n) {
  var agendada = modoN8n === 'production' || modoN8n === 'trigger';
  var producao = cfg.modoTeste === false && agendada;
  return { producao: producao, para: producao ? cfg.lista : cfg.emailTeste, prefixo: producao ? '' : '[TESTE] ' };
}
function ehTeste(op) { return /^\s*\[TESTE\]/i.test(txt(op.titulo)) || /^\s*\[TESTE\]/i.test(txt(op.titulo_oficial)); }

// ---------- oportunidade ----------
function ehApiTransferegov(u) { return /^https?:\/\/api-publica\.transferegov\./i.test(txt(u)); }
// Link para leitura de gente. Programa do Transferegov não tem página pública (a API devolve JSON): vai o caminho de envio e a instrução de busca.
function linkOp(op) {
  var cands = [seguro(op.link_edital_oficial), seguro(op.url)].filter(Boolean);
  var normal = cands.filter(function (u) { return !ehApiTransferegov(u); })[0] || '';
  var prog = txt(op.tipo_oportunidade) === 'programa_aberto';
  if (normal) return { tg: false, url: normal, rotulo: prog ? 'Programa' : 'Edital oficial' };
  if (cands.some(ehApiTransferegov) || prog) return { tg: true, url: TG_ENVIO, rotulo: TG_ROTULO };
  return { tg: false, url: '', rotulo: 'Edital oficial' };
}
function infoOp(op) {
  return {
    chave: txt(op.chave), titulo: txt(op.titulo_oficial) || txt(op.titulo), ofertante: txt(op.ofertante), prazo: dia(op.prazo), valor: txt(op.valor),
    resumo: txt(op.resumo), publico: txt(op.publico_elegivel), papel: txt(op.papel_modal), fonte: txt(op.fonte), prog: txt(op.tipo_oportunidade) === 'programa_aberto',
    link: linkOp(op), teste: ehTeste(op)
  };
}
function papelRotulo(papel) {
  if (papel === 'parceira') return ROTULO_PARCEIRA;
  if (papel === 'proponente') return 'O Modal pode ser o proponente (ICT)';
  return 'Papel do Modal a confirmar no edital';
}

// ---------- blocos de e-mail (formato do subfluxo "Modal – Enviar e-mail") ----------
function P(html) { return { tipo: 'paragrafo', html: html }; }
function PT(texto) { return { tipo: 'paragrafo', texto: texto }; }
function H(texto) { return { tipo: 'subtitulo', texto: texto }; }
function UL(itens) { return { tipo: 'lista', itens: itens }; }
function AV(texto, tom) { return { tipo: 'aviso', texto: texto, tom: tom || 'atencao' }; }
function CAMPOS(itens, titulo) { return { tipo: 'campos', titulo: titulo, itens: itens }; }
function BOTOES(itens) { return { tipo: 'botoes', itens: itens }; }
function blocoLink(op) {
  var i = op.link ? op : infoOp(op);
  if (i.link.tg) return P('<b>Programa no Transferegov:</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.rotulo) + '</a>. No portal, busque pelo nome do programa: <i>' + esc(i.titulo) + '</i>.');
  if (i.link.url) return P('<b>' + esc(i.prog ? 'Programa oficial' : 'Edital oficial') + ':</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.url) + '</a>');
  return PT('Link do edital não identificado; procure no site do ofertante.');
}
function urlDecisao(token, d) { return BASE_DECISAO + '?t=' + encodeURIComponent(token) + '&d=' + d; }
function botoesDecisao(token) { return BOTOES([{ rotulo: 'Vamos concorrer', url: urlDecisao(token, 'concorrer') }, { rotulo: 'Talvez', url: urlDecisao(token, 'talvez') }, { rotulo: 'Não serve', url: urlDecisao(token, 'nao_serve') }]); }
function novoEmail(cfg, ctx, e) {
  return {
    para: ctx.para, assunto: ctx.prefixo + e.assunto, nomeRemetente: cfg.remetente, responderPara: cfg.lista,
    etiqueta: e.etiqueta, titulo: e.titulo, previa: e.previa, blocos: e.blocos, rodape: RODAPE, _marca: e.marca || null
  };
}

// ---------- resposta do subfluxo de e-mail ----------
// O subfluxo devolve a resposta do Gmail (tem "id") ou falha. Só conta como enviado o que voltou com id.
function enviado(resp) { return !!(resp && typeof resp === 'object' && !resp.error && typeof resp.id === 'string' && resp.id); }

// Captação – Avaliação: funções puras (testadas com carregar.js). Embutido depois de comum.js.

var LIMITE_TEXTO = 120000;
var PASSO_CERT = 'Emitir as certidões exigidas (federal, FGTS, trabalhista, DF) perto da entrega; o pacote de quem decide concorrer traz os links.';
var PASSO_PARCEIRA = 'Ver qual cliente ou parceiro do Modal poderia propor esta chamada e convidá-lo a entrar com o Modal (a empresa propõe; o Modal entra como ICT parceira).';
var CERT_RX = /certid[aã]o|certid[oõ]es|\bcnd\b|cndt|regularidade (do|com o|perante o) fgts|\bfgts\b|d[eé]bitos trabalhistas|regularidade fiscal/i;
var PERFIL_MODAL = 'Instituto Modal: ICT (Instituição Científica, Tecnológica e de Inovação) privada sem fins lucrativos, associação sediada em Brasília-DF desde 2017. NÃO é OSCIP.';

function ehCertidao(x) { return /^certid/i.test(txt(x['Seção'])) || /certid[aã]o negativa|regularidade do fgts|d[eé]bitos trabalhistas/i.test(txt(x['Item'])); }

function lerHtml(html) {
  var h = String(html || '').replace(/<(script|style|noscript|svg)\b[\s\S]*?<\/\1>/gi, ' ').replace(/<(nav|header|footer)\b[\s\S]*?<\/\1>/gi, ' ');
  var t = h.replace(/<(br|p|div|li|tr|h[1-6]|section|article|dt|dd)\b[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' ');
  t = t.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>');
  return t.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
}

// Fila da rodada. o: { aprovadas, avaliacoes, dossie, carteira, organizacao (linhas da aba), hoje, producao, limite }
// Oportunidade aprovada sem linha de avaliação, do prazo mais próximo ao mais distante; vencida não é avaliada; "[TESTE]" só fora da produção.
function montarFila(o) {
  var existentes = {};
  (o.avaliacoes || []).forEach(function (a) { if (a && a.chave_oportunidade) existentes[a.chave_oportunidade] = true; });
  var org = (o.organizacao || []).filter(function (r) { return r && txt(r['Organização']); })[0] || {};
  var dossie = (o.dossie || []).filter(function (d) { return d && txt(d['Item']); });
  var carteira = (o.carteira || []).filter(function (c) { return c && txt(c['Projeto']); });
  var cand = [];
  (o.aprovadas || []).forEach(function (op) {
    if (!op || !op.chave || op.situacao_triagem !== 'aprovada' || op.duplicata_de) return;
    if (existentes[op.chave]) return;
    if (o.producao && ehTeste(op)) return;
    var prazo = dia(op.prazo);
    if (prazo && prazo < o.hoje) return;
    cand.push({ op: op, prazo: prazo });
  });
  cand.sort(porPrazo);
  var semCert = dossie.filter(function (x) { return !ehCertidao(x); });
  var lacunas = semCert.filter(function (x) { return /^(falta|verificar)/i.test(txt(x['Situação'])); }).length;
  var motivosBase = [];
  if (!dossie.length) motivosBase.push('o dossiê da organização está vazio');
  else if (lacunas >= Math.max(5, Math.ceil(semCert.length / 3))) motivosBase.push(lacunas + ' de ' + semCert.length + ' itens do dossiê (fora as certidões) constam como "Falta" ou "Verificar"');
  if (!carteira.length) motivosBase.push('a carteira de projetos está vazia');
  var dossieTxt = semCert.map(function (x) {
    return '- [' + txt(x['Seção']) + '] ' + txt(x['Item']) + ': ' + (txt(x['Situação']) || 'sem situação') + (txt(x['Validade']) ? '; validade ' + txt(x['Validade']) : '') + (txt(x['Observação']) ? ' — ' + txt(x['Observação']).slice(0, 350) : '');
  }).join('\n') + (dossie.length > semCert.length ? '\n- [Certidões] Certidões negativas (federal, FGTS, trabalhista, DF): emitidas só quando a organização decide concorrer, perto da entrega; NÃO contam como falta nesta avaliação.' : '');
  var carteiraTxt = carteira.map(function (c) {
    return '- ' + txt(c['Projeto']) + ' (' + (txt(c['Situação']) || 'sem situação') + '): público: ' + txt(c['Público']) + '; problema: ' + txt(c['Problema que resolve']) + '; atividades: ' + txt(c['Principais atividades']) + '; orçamento estimado R$ ' + txt(c['Orçamento estimado (R$)']) + '; duração ' + txt(c['Duração (meses)']) + ' meses; impacto: ' + txt(c['Impacto esperado e indicadores']) + '; temas: ' + txt(c['Temas']);
  }).join('\n');
  return cand.slice(0, o.limite || 10).map(function (c) {
    var op = c.op, url = seguro(op.link_edital_oficial) || seguro(op.url);
    var semPagina = !url || !!txt(op.texto_fonte) && (ehApiTransferegov(url) || ehApiTransferegov(op.url) || /^https?:\/\/(ec\.europa\.eu|api\.tech\.ec\.europa\.eu)\//i.test(url));
    return {
      chave: op.chave, url: url, leitura: semPagina ? 'sem_pagina' : 'buscar', texto_fonte: txt(op.texto_fonte), tipo_oportunidade: txt(op.tipo_oportunidade) || 'edital',
      papel_modal: txt(op.papel_modal), prazo: c.prazo,
      op: { titulo: txt(op.titulo_oficial) || txt(op.titulo), ofertante: txt(op.ofertante), numero_edital: txt(op.numero_edital), tipo_instrumento: txt(op.tipo_instrumento), publico_elegivel: txt(op.publico_elegivel), regiao: txt(op.regiao), prazo: c.prazo, valor: txt(op.valor), temas: txt(op.temas), resumo: txt(op.resumo), link: url },
      org_perfil: { areas: txt(org['Áreas de atuação']), publico: txt(org['Público atendido']), regiao: txt(org['Região']), observacoes: txt(org['Observação']) },
      dossie_txt: dossieTxt, carteira_txt: carteiraTxt, projetos: carteira.map(function (x) { return txt(x['Projeto']); }), motivos_parcial: motivosBase.slice()
    };
  });
}

// Texto do edital: PDF (resp.text), página (resp.data), erro ou nada; o texto guardado na coleta entra junto. Cortado em 120 mil caracteres.
function prepararTexto(f, resp) {
  resp = resp || {};
  var base = txt(f.texto_fonte), pag = '', fonte = '';
  if (f.leitura !== 'sem_pagina' && !resp.error) {
    if (typeof resp.text === 'string') { pag = resp.text; fonte = 'PDF'; }
    else if (typeof resp.data === 'string') { pag = lerHtml(resp.data); fonte = 'página'; }
  }
  pag = String(pag || '').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
  var texto = pag && base && tam(pag) < 400 ? base + '\n\n--- PÁGINA ---\n' + pag : (pag || base);
  if (!pag || tam(pag) < 400) fonte = base ? 'texto da coleta' : fonte;
  var cortado = texto.length > LIMITE_TEXTO;
  return { texto: texto.slice(0, LIMITE_TEXTO), fonte: fonte || 'página', cortado: cortado, leitura_ok: tam(texto) >= 400 };
}

function montarPedido(f, p, hoje) {
  var motivos = f.motivos_parcial.slice();
  if (!p.leitura_ok) motivos.unshift('o edital não pôde ser lido por inteiro; avaliação feita só com os dados da triagem');
  var op = f.op, o = f.org_perfil;
  var prog = f.tipo_oportunidade === 'programa_aberto';
  var notaPrograma = prog ? 'TIPO DE OPORTUNIDADE: programa federal ABERTO A PROPOSTAS VOLUNTÁRIAS no Transferegov, sem chamamento e sem seleção competitiva. A organização cadastra proposta e plano de trabalho no Transferegov até a data limite do programa; o órgão analisa o enquadramento e a disponibilidade orçamentária e pode ou não celebrar a parceria: não há garantia de recurso nem classificação entre concorrentes. Avalie assim: a aderência mede o encaixe do objeto do programa com o Modal e a capacidade de propor e executar; recomendação "seguir" significa que vale cadastrar a proposta, não que o recurso é provável; a justificativa deve dizer, em uma frase, que é programa aberto a propostas, sem seleção e sem garantia de recurso; os próximos passos devem incluir cadastrar a proposta no Transferegov até a data limite e buscar apoio para o repasse junto à área técnica do órgão concedente. Não fale em classificação nem nota de corte.\n\n' : '';
  var notaParceira = f.papel_modal === 'parceira' ? 'PAPEL DO MODAL NESTA OPORTUNIDADE: quem propõe é uma EMPRESA; o Modal entra como ICT parceira (executora) da empresa proponente, não como proponente. Avalie o encaixe do Modal como ICT parceira (capacidade técnica, áreas, clientes e parceiros do Modal no setor) e inclua nos próximos passos ver qual cliente ou parceiro do Modal poderia propor e convidá-lo a entrar com o Modal.\n\n' : '';
  var prompt = 'Hoje é ' + hoje + '. Avalie se o Modal deve ir atrás desta oportunidade.\n\n' +
    'PERFIL FIXO: ' + PERFIL_MODAL + '\n\n' +
    'OPORTUNIDADE (dados da triagem)\n- Título: ' + op.titulo + '\n- Tipo de oportunidade: ' + (prog ? 'programa aberto a propostas voluntárias, sem seleção' : 'edital ou chamada') + '\n- Ofertante: ' + op.ofertante + '\n- Número: ' + (op.numero_edital || 'não informado') + '\n- Tipo: ' + op.tipo_instrumento + '\n- Quem pode concorrer: ' + op.publico_elegivel + '\n- Região: ' + op.regiao + '\n- Prazo: ' + (op.prazo || 'não informado') + '\n- Valor: ' + (op.valor || 'não informado') + '\n- Temas: ' + op.temas + '\n- Resumo: ' + op.resumo + '\n- Link oficial: ' + (ehApiTransferegov(op.link) ? '(programa do Transferegov; sem página pública)' : op.link) + '\n\n' +
    'ORGANIZAÇÃO (planilha)\n- Áreas de atuação: ' + o.areas + '\n- Público atendido: ' + o.publico + '\n- Região: ' + o.regiao + (o.observacoes ? '\n- Observação: ' + o.observacoes : '') + '\n\n' +
    'DOSSIÊ DO MODAL (item: situação; "Tem" = documento em ordem; "Falta" = o Modal ainda não tem; "Não tem" = não possui (se o edital exigir, é impeditivo ou precisa ser providenciado); "Não se aplica" = só é providenciado quando um projeto exige, não conta como falta; "Verificar" = ainda não conferido)\n' + (f.dossie_txt || '(vazio)') + '\n\n' +
    'CARTEIRA DE PROJETOS DO MODAL\n' + (f.carteira_txt || '(vazia: ainda não há projetos cadastrados)') + '\n\n' +
    notaParceira + notaPrograma +
    (motivos.length ? 'Esta avaliação será marcada como parcial (' + motivos.join('; ') + '); o aviso de parcialidade é acrescentado automaticamente, então não o repita na justificativa.\n\n' : '') +
    'CERTIDÕES: certidões negativas (federal, FGTS, trabalhista, DF) são emitidas só quando o Modal decide concorrer, perto da entrega. Não use a falta ou o vencimento delas para reduzir a aderência ou a recomendação, não as cite na justificativa e não as liste em requisitos_atendidos, requisitos_faltantes nem em proximos_passos (o passo de emitir certidões é acrescentado automaticamente).\n\n' +
    'Instruções:\n' +
    '- aderencia: 0 a 100, o quanto o objeto e o público elegível combinam com o Modal e com a capacidade real dele de cumprir as exigências.\n' +
    '- recomendacao: seguir (vale ir atrás), avaliar (pode valer, depende de algo a confirmar) ou nao_seguir.\n' +
    '- justificativa: no máximo 3 frases curtas e concretas.\n' +
    '- projeto_sugerido: o nome exato de um projeto da carteira que se encaixa; vazio se nenhum se encaixa ou se a carteira está vazia.\n' +
    '- esforco: baixo, medio ou alto, considerando documentos a reunir, proposta a escrever e o tempo até o prazo.\n' +
    '- requisitos_atendidos e requisitos_faltantes: cruze as exigências com o dossiê. Um item curto por elemento; não liste o que o edital não exige.\n' +
    '- proximos_passos: 2 a 5 ações práticas, em ordem, com data quando fizer sentido.\n' +
    '- Não invente exigências, valores nem dados que não estejam no edital ou no dossiê.\n\n' +
    'TEXTO DO EDITAL (' + (p.leitura_ok ? p.fonte + (p.cortado ? ', cortado nos primeiros ' + LIMITE_TEXTO + ' caracteres' : '') : 'não lido') + ')\n' + (p.leitura_ok ? p.texto : '(não foi possível ler o edital completo; avalie só com os dados da triagem acima)');
  return { prompt: prompt, leitura_ok: p.leitura_ok, fonte: p.fonte, motivos_parcial: motivos };
}

var ESQUEMA_AVALIACAO = {
  type: 'object',
  properties: {
    aderencia: { type: 'integer', description: '0 a 100' },
    recomendacao: { type: 'string', enum: ['seguir', 'avaliar', 'nao_seguir'] },
    justificativa: { type: 'string' },
    projeto_sugerido: { type: 'string', description: 'nome exato de um projeto da carteira ou vazio' },
    esforco: { type: 'string', enum: ['baixo', 'medio', 'alto'] },
    requisitos_atendidos: { type: 'array', items: { type: 'string' } },
    requisitos_faltantes: { type: 'array', items: { type: 'string' } },
    proximos_passos: { type: 'array', items: { type: 'string' } }
  },
  required: ['aderencia', 'recomendacao', 'justificativa', 'projeto_sugerido', 'esforco', 'requisitos_atendidos', 'requisitos_faltantes', 'proximos_passos']
};
var SISTEMA_AVALIACAO = 'Você é especialista em captação de recursos para instituições científicas e de inovação do Distrito Federal. Avalia editais com realismo: confere as exigências contra os documentos e projetos que a instituição tem, não superestima a aderência, aponta o que falta e escreve em português claro e direto, para quem vai decidir se vai atrás.';

// Valida a saída da IA e monta a linha da avaliação. Saída inválida ou token malformado: gravar=false (nada é gravado; volta na rodada seguinte).
function linhaAvaliacao(f, pedido, ia, token, agoraIso) {
  if (!ia || typeof ia !== 'object' || Array.isArray(ia)) return { gravar: false, motivo: 'saída da IA ausente ou inválida' };
  if (!/^[a-f0-9]{48}$/.test(String(token || ''))) return { gravar: false, motivo: 'token gerado em formato inesperado' };
  var ad = Number(ia.aderencia);
  if (!isFinite(ad)) return { gravar: false, motivo: 'aderência inválida' };
  ad = Math.max(0, Math.min(100, Math.round(ad)));
  if (['seguir', 'avaliar', 'nao_seguir'].indexOf(ia.recomendacao) < 0) return { gravar: false, motivo: 'recomendação inválida' };
  var justificativa = txt(ia.justificativa);
  if (!justificativa) return { gravar: false, motivo: 'justificativa vazia' };
  var esf = ['baixo', 'medio', 'alto'].indexOf(ia.esforco) >= 0 ? ia.esforco : 'medio';
  // projeto sugerido só vale se existir na carteira (nome igual, sem caixa)
  var proj = txt(ia.projeto_sugerido).toLowerCase();
  var projetos = f.projetos || [];
  var projOk = !proj ? '' : (projetos.filter(function (x) { return x.toLowerCase() === proj; })[0] || projetos.filter(function (x) { return x.toLowerCase().indexOf(proj) >= 0 || proj.indexOf(x.toLowerCase()) >= 0; })[0] || '');
  // certidões ficam fora dos requisitos (não reduzem a aderência) e viram um passo fixo
  var atendidos = itensDe(ia.requisitos_atendidos).filter(function (s) { return !CERT_RX.test(s); });
  var faltantes = itensDe(ia.requisitos_faltantes).filter(function (s) { return !CERT_RX.test(s); });
  var passos = itensDe(ia.proximos_passos).filter(function (s) { return !CERT_RX.test(s); });
  if (f.papel_modal === 'parceira' && !passos.some(function (s) { return /empresa/i.test(s); })) passos.unshift(PASSO_PARCEIRA);
  passos.push(PASSO_CERT);
  var motivos = pedido.motivos_parcial || [];
  var parcial = motivos.length > 0;
  var just = justificativa.replace(/^(a\s+)?avalia[cç][aã]o\s+(é\s+)?parcial[:.,]?\s*/i, '');
  if (just) just = just.charAt(0).toUpperCase() + just.slice(1);
  if (parcial) just = 'Avaliação parcial: ' + motivos.join('; ') + '. ' + just;
  var junta = function (a) { return a.join('\n').slice(0, 3000); };
  return {
    gravar: true,
    linha: {
      chave_oportunidade: f.chave, situacao: 'nova', aderencia: ad, recomendacao: ia.recomendacao, justificativa: just.slice(0, 2000), projeto_sugerido: projOk, esforco: esf,
      requisitos_atendidos: junta(atendidos), requisitos_faltantes: junta(faltantes), proximos_passos: junta(passos), avaliacao_parcial: parcial,
      avaliado_em: agoraIso, token: token, atualizacao_pendente: false, lembretes_enviados: '', pedidos_resultado: 0
    }
  };
}

// Captação – Acompanhamento: pacote "Vamos concorrer", lembretes 14/7/3/1, "Vocês enviaram?" e pedidos de resultado.
// Funções puras; embutido depois de comum.js e avaliacao.js (ehCertidao, lerHtml, LIMITE_TEXTO).

var MARCOS = [14, 7, 3, 1];
var LIMITE_PACOTES = 3;
var PADRAO_DIAS = 25;
var ESQUEMA_LEITURA = {
  type: 'object',
  properties: {
    documentos_exigidos: { type: 'array', items: { type: 'string' } },
    exige_certidoes: { type: 'string', enum: ['sim', 'nao', 'nao_informado'] },
    certidoes: { type: 'array', items: { type: 'string', enum: ['federal', 'fgts', 'trabalhista', 'df'] } },
    outras_certidoes: { type: 'array', items: { type: 'string' } },
    itens_dossie_exigidos: { type: 'array', items: { type: 'object', properties: { item: { type: 'string', description: 'nome exato do item do dossiê' }, trecho: { type: 'string', description: 'frase do edital, copiada literalmente, que exige este item' } }, required: ['item', 'trecho'] } },
    forma_entrega: { type: 'string' },
    prazo_no_edital: { type: 'string', description: 'AAAA-MM-DD ou vazio' }
  },
  required: ['documentos_exigidos', 'exige_certidoes', 'certidoes', 'outras_certidoes', 'itens_dossie_exigidos', 'forma_entrega', 'prazo_no_edital']
};
var SISTEMA_LEITURA = 'Você ajuda uma instituição científica e de inovação do Distrito Federal a preparar propostas para editais. Lê o edital com atenção e extrai só o que está escrito nele, em português claro e curto. Não inventa exigências. Em itens_dossie_exigidos, para cada item informe em "trecho" a frase do edital, copiada literalmente (de 10 a 200 caracteres), que exige aquele documento ou registro; se nenhuma frase do edital o exige expressamente, não inclua o item. Em documentos_exigidos não liste certidões negativas nem certificados de regularidade (eles vão em certidoes).';

function enviadosDe(a) { return txt(a.lembretes_enviados).split(',').map(function (s) { return Number(s.trim()); }).filter(function (n) { return n > 0; }); }

// ---------- o que sai nesta rodada ----------
// o: { avaliacoes, oportunidades, ctx, hoje, hora, agoraIso }. Cada coisa sai uma vez por avaliação; as colunas de controle só são gravadas depois do envio confirmado.
function planejar(o) {
  var ops = {};
  (o.oportunidades || []).forEach(function (x) { if (x && x.chave) ops[x.chave] = x; });
  // lembretes e pedidos só em horário comercial (8h às 20h) em produção; o pacote sai em qualquer rodada
  var janela = !o.ctx.producao || (o.hora >= 8 && o.hora < 20);
  var hoje = o.hoje, tarefas = [], pacotes = 0;
  (o.avaliacoes || []).forEach(function (a) {
    if (!a || !a.id || !a.chave_oportunidade) return;
    if (a.situacao !== 'concorrer' && a.situacao !== 'enviada') return;
    var op = ops[a.chave_oportunidade]; if (!op) return;
    // produção ignora oportunidades de teste; fora da produção só as de teste são tocadas
    if (o.ctx.producao === ehTeste(op)) return;
    var prazo = dia(op.prazo), dias = prazo ? diasEntre(hoje, prazo) : null;
    var base = { avaliacao_id: a.id, chave: a.chave_oportunidade, prazo: prazo, dias: dias, hoje: hoje };
    if (a.situacao === 'concorrer') {
      if (!a.pacote_enviado_em && !(prazo && dias < 0)) {
        var ini = a.pacote_iniciado_em ? Date.parse(String(a.pacote_iniciado_em)) : NaN;
        if (!isNaN(ini) && (Date.parse(o.agoraIso) - ini) < 30 * 60000) return; // outra rodada está montando
        if (pacotes >= LIMITE_PACOTES) return;
        pacotes++;
        tarefas.push(Object.assign({ tipo: 'pacote', url: seguro(op.link_edital_oficial) || seguro(op.url), leitura: leituraDe(op) }, base));
        return;
      }
      if (!janela) return;
      if (prazo && dias >= 1) {
        if (!a.pacote_enviado_em) return;
        var feitos = enviadosDe(a);
        var devidos = MARCOS.filter(function (m) { return m >= dias; });
        if (!devidos.length) return;
        var marco = Math.min.apply(null, devidos); // marco perdido não gera envio atrasado do anterior: só o mais próximo
        if (feitos.indexOf(marco) >= 0) return;
        var novos = feitos.concat(devidos).filter(function (v, i, arr) { return arr.indexOf(v) === i; }).sort(function (x, y) { return y - x; });
        tarefas.push(Object.assign({ tipo: 'lembrete', marco: marco, lembretes_novos: novos.join(',') }, base));
        return;
      }
      if (a.pedido_envio_em) return;
      if (prazo && dias < 0) { tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base)); return; }
      var dec = dia(a.decidido_em); // sem prazo registrado: pergunta uma vez, 30 dias depois da decisão
      if (!prazo && dec && hoje >= somaDias(dec, 30)) tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base));
      return;
    }
    // enviada: pedido de resultado 30 dias após o prazo e mais um 30 dias depois; nunca mais de dois
    if (!janela) return;
    var env = dia(a.enviada_em), ref = prazo || env;
    if (!ref) return;
    var n = Number(a.pedidos_resultado) || 0;
    if (n >= 2) return;
    var devido = n === 0 ? (hoje >= somaDias(ref, 30) && (!env || hoje >= somaDias(env, 7))) : (hoje >= somaDias(ref, 60) && hoje >= somaDias(dia(a.pedido_resultado_em) || ref, 30));
    if (devido) tarefas.push(Object.assign({ tipo: 'pedido_resultado', pedidos_novos: n + 1 }, base));
  });
  return tarefas;
}
function leituraDe(op) {
