    else if (val && val < hoje) estado = 'Vencido em ' + val;
    else if (val && f.prazo && val <= f.prazo) estado = 'Vence em ' + val + ', antes do prazo do edital';
    linhas.push('- ' + txt(d['Item']) + ': ' + (estado || sit || 'sem situação'));
    if (estado) pend.push({ item: txt(d['Item']), estado: estado });
  });
