};
var SISTEMA_LEITURA = 'Você ajuda uma instituição científica e de inovação do Distrito Federal a preparar propostas para editais. Lê o edital com atenção e extrai só o que está escrito nele, em português claro e curto. Não inventa exigências. Em itens_dossie_exigidos, para cada item informe em "trecho" a frase do edital, copiada literalmente (de 10 a 200 caracteres), que exige aquele documento ou registro; se nenhuma frase do edital o exige expressamente, não inclua o item. Em documentos_exigidos não liste certidões negativas nem certificados de regularidade (eles vão em certidoes).';

function enviadosDe(a) { return txt(a.lembretes_enviados).split(',').map(function (s) { return Number(s.trim()); }).filter(function (n) { return n > 0; }); }

// ---------- o que sai nesta rodada ----------
// o: { avaliacoes, oportunidades, ctx, hoje, hora, agoraIso }. Cada coisa sai uma vez por avaliação; as colunas de controle só são gravadas depois do envio confirmado.
function planejar(o) {
  var ops = {};
  (o.oportunidades || []).forEach(function (x) { if (x && x.chave) ops[x.chave] = x; });
  // lembretes e pedidos só em horário comercial (8h às 20h) em produção; o pacote sai em qualquer rodada
  var janela = !o.ctx.producao || (o.hora >= 8 && o.hora < 20);
  var hoje = o.hoje, tarefas = [], pacotes = 0;
  (o.avaliacoes || []).forEach(function (a) {
    if (!a || !a.id || !a.chave_oportunidade) return;
    if (a.situacao !== 'concorrer' && a.situacao !== 'enviada') return;
    var op = ops[a.chave_oportunidade]; if (!op) return;
    // produção ignora oportunidades de teste; fora da produção só as de teste são tocadas
    if (o.ctx.producao === ehTeste(op)) return;
    var prazo = dia(op.prazo), dias = prazo ? diasEntre(hoje, prazo) : null;
    var base = { avaliacao_id: a.id, chave: a.chave_oportunidade, prazo: prazo, dias: dias, hoje: hoje };
    if (a.situacao === 'concorrer') {
      if (!a.pacote_enviado_em && !(prazo && dias < 0)) {
        var ini = a.pacote_iniciado_em ? Date.parse(String(a.pacote_iniciado_em)) : NaN;
        if (!isNaN(ini) && (Date.parse(o.agoraIso) - ini) < 30 * 60000) return; // outra rodada está montando
        if (pacotes >= LIMITE_PACOTES) return;
        pacotes++;
        tarefas.push(Object.assign({ tipo: 'pacote', url: seguro(op.link_edital_oficial) || seguro(op.url), leitura: leituraDe(op) }, base));
        return;
      }
      if (!janela) return;
      if (prazo && dias >= 1) {
        if (!a.pacote_enviado_em) return;
        var feitos = enviadosDe(a);
        var devidos = MARCOS.filter(function (m) { return m >= dias; });
        if (!devidos.length) return;
        var marco = Math.min.apply(null, devidos); // marco perdido não gera envio atrasado do anterior: só o mais próximo
        if (feitos.indexOf(marco) >= 0) return;
        var novos = feitos.concat(devidos).filter(function (v, i, arr) { return arr.indexOf(v) === i; }).sort(function (x, y) { return y - x; });
        tarefas.push(Object.assign({ tipo: 'lembrete', marco: marco, lembretes_novos: novos.join(',') }, base));
        return;
      }
      if (a.pedido_envio_em) return;
      if (prazo && dias < 0) { tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base)); return; }
      var dec = dia(a.decidido_em); // sem prazo registrado: pergunta uma vez, 30 dias depois da decisão
      if (!prazo && dec && hoje >= somaDias(dec, 30)) tarefas.push(Object.assign({ tipo: 'pedido_envio' }, base));
      return;
    }
